INSERT INTO public.translations (key, lang, text, domain) VALUES
  ('question.1.prompt', 'pt-BR', 'Você recebe sua mesada do mês. Depois de cobrir os gastos fixos, sobram R$ 600.', 'question'),
  ('question.1.opt.A.text', 'pt-BR', 'Coloco em algo que possa render bem, mesmo que seja arriscado', 'question'),
  ('question.1.opt.B.text', 'pt-BR', 'Pesquiso na internet opções como o Tesouro Direto ou fundos antes de decidir', 'question'),
  ('question.1.opt.C.text', 'pt-BR', 'Guardo na minha conta e não mexo, prefiro ter o dinheiro seguro', 'question'),
  ('question.1.opt.D.text', 'pt-BR', 'Pergunto para alguém que entende de dinheiro o que me convém', 'question'),
  ('question.2.prompt', 'pt-BR', 'Seu melhor amigo propõe que você seja sócio em um negócio. Você precisa colocar R$ 1.500. Vários do grupo já disseram que sim.', 'question'),
  ('question.2.opt.A.text', 'pt-BR', 'Se vários já entraram e confio no meu amigo, entro também', 'question'),
  ('question.2.opt.B.text', 'pt-BR', 'Digo que não, prefiro não arriscar meu dinheiro em algo incerto', 'question'),
  ('question.2.opt.C.text', 'pt-BR', 'Peço o plano de negócio, os números, e decido com base nisso', 'question'),
  ('question.2.opt.D.text', 'pt-BR', 'A ideia me anima, entro de imediato e quero participar ativamente', 'question'),
  ('question.3.prompt', 'pt-BR', 'No seu grupo de amigos todos falam de uma cripto que subiu 40% em uma semana. Vários já compraram e estão te pressionando para entrar.', 'question'),
  ('question.3.opt.A.text', 'pt-BR', 'Busco informação por conta própria antes de investir um centavo', 'question'),
  ('question.3.opt.B.text', 'pt-BR', 'Não me importa o que digam, não entro em coisas que não entendo bem', 'question'),
  ('question.3.opt.C.text', 'pt-BR', 'Se tanta gente está ganhando, algo de verdade deve haver, coloco uma quantia moderada', 'question'),
  ('question.3.opt.D.text', 'pt-BR', 'Entro com tudo, esse tipo de oportunidade não aparece duas vezes', 'question'),
  ('question.4.prompt', 'pt-BR', 'É uma promoção especial e você vê um notebook com 35% de desconto. Não precisa dele com urgência, mas a oferta acaba em 24 horas.', 'question'),
  ('question.4.opt.A.text', 'pt-BR', 'Compro, essas oportunidades não se repetem', 'question'),
  ('question.4.opt.B.text', 'pt-BR', 'Comparo specs, reviews, preços em outras lojas e, se valer a pena, compro', 'question'),
  ('question.4.opt.C.text', 'pt-BR', 'Não compro, prefiro guardar esse dinheiro caso apareça algo que realmente precise', 'question'),
  ('question.4.opt.D.text', 'pt-BR', 'Pergunto a alguém que entenda de tecnologia se realmente vale a pena', 'question'),
  ('question.5.prompt', 'pt-BR', 'Você quer fazer um intercâmbio. Precisa juntar R$ 25.000 em 10 meses. Hoje você tem R$ 0 poupados.', 'question'),
  ('question.5.opt.A.text', 'pt-BR', 'Monto um plano detalhado: quanto poupar por mês, em qual instrumento, com datas', 'question'),
  ('question.5.opt.B.text', 'pt-BR', 'Peço ajuda aos meus pais ou busco uma bolsa, sozinho acho que não consigo', 'question'),
  ('question.5.opt.C.text', 'pt-BR', 'Sinto que é impossível, melhor buscar opções mais baratas', 'question'),
  ('question.5.opt.D.text', 'pt-BR', 'Busco gerar renda extra de onde for — freelance, venda de coisas', 'question'),
  ('question.6.prompt', 'pt-BR', 'O banco te oferece seu primeiro cartão de crédito com um limite de R$ 4.000.', 'question'),
  ('question.6.opt.A.text', 'pt-BR', 'Aceito na hora, ter crédito abre portas', 'question'),
  ('question.6.opt.B.text', 'pt-BR', 'Pesquiso a taxa, CET, anuidade e comparo com outras opções', 'question'),
  ('question.6.opt.C.text', 'pt-BR', 'Não quero, cartões de crédito te endividam', 'question'),
  ('question.6.opt.D.text', 'pt-BR', 'Pergunto a alguém da minha família se é boa ideia', 'question'),
  ('question.7.prompt', 'pt-BR', 'Você vê um anúncio no Instagram de um curso de trading com depoimentos de pessoas que "já vivem disso". Custa R$ 900.', 'question'),
  ('question.7.opt.A.text', 'pt-BR', 'Se tanta gente recomenda, algo de bom deve ter, me inscrevo', 'question'),
  ('question.7.opt.B.text', 'pt-BR', 'Busco avaliações independentes, revejo o currículo e o instrutor antes de pagar', 'question'),
  ('question.7.opt.C.text', 'pt-BR', 'Chama minha atenção, mas R$ 900 é muito, melhor não arriscar', 'question'),
  ('question.7.opt.D.text', 'pt-BR', 'Me inscrevo já, se não funcionar ao menos aprendi algo', 'question'),
  ('question.8.prompt', 'pt-BR', 'Você recebe seu primeiro décimo terceiro de um estágio: R$ 2.500. É um dinheiro que não esperava.', 'question'),
  ('question.8.opt.A.text', 'pt-BR', 'Coloco tudo em algo agressivo — ações, cripto — afinal é dinheiro extra', 'question'),
  ('question.8.opt.B.text', 'pt-BR', 'Deixo na minha conta poupança, assim sei que está seguro', 'question'),
  ('question.8.opt.C.text', 'pt-BR', 'Pergunto em casa ou a um professor de finanças o que seria mais inteligente', 'question'),
  ('question.8.opt.D.text', 'pt-BR', 'Comparo rendimentos do Tesouro Direto, CDBs e fundos', 'question'),
  ('question.9.prompt', 'pt-BR', 'Você está prestes a se formar. Tem uma oferta de emprego estável com bom salário, mas também uma ideia de negócio que te apaixona.', 'question'),
  ('question.9.opt.A.text', 'pt-BR', 'Analiso as duas opções a fundo: projeções, custos, mercado, e decido com dados', 'question'),
  ('question.9.opt.B.text', 'pt-BR', 'Entro no negócio, a vida é uma só e não quero me arrepender de não tentar', 'question'),
  ('question.9.opt.C.text', 'pt-BR', 'Fico com o emprego seguro, preciso de estabilidade', 'question'),
  ('question.9.opt.D.text', 'pt-BR', 'Converso com pessoas que admiro profissionalmente e sigo o conselho que mais se repetir', 'question'),
  ('question.10.prompt', 'pt-BR', 'Um colega de aula te mostra um app onde você investe a partir de R$ 30. Ele te mostra que está com 15% de rendimento em 3 meses.', 'question'),
  ('question.10.opt.A.text', 'pt-BR', 'Coloco um pouco para ver o que acontece, afinal é pouco dinheiro', 'question'),
  ('question.10.opt.B.text', 'pt-BR', 'Baixo o app, verifico quem o regulamenta, leio os termos e depois decido', 'question'),
  ('question.10.opt.C.text', 'pt-BR', 'Parece bom, mas prefiro esperar — não gosto de colocar dinheiro em coisas novas', 'question'),
  ('question.10.opt.D.text', 'pt-BR', 'Se está funcionando para o meu colega, entro com o mesmo valor que ele', 'question'),
  ('question.11.prompt', 'pt-BR', 'Você recebe uma herança inesperada de R$ 60.000. Não tem dívidas.', 'question'),
  ('question.11.opt.A.text', 'pt-BR', 'Divido em diferentes instrumentos de maior risco para fazer o capital crescer', 'question'),
  ('question.11.opt.B.text', 'pt-BR', 'Monto um portfólio diversificado com base no meu horizonte de investimento e perfil', 'question'),
  ('question.11.opt.C.text', 'pt-BR', 'Coloco em uma conta poupança de alta segurança, não quero arriscar nada', 'question'),
  ('question.11.opt.D.text', 'pt-BR', 'Peço conselho ao meu assessor bancário ou a alguém de confiança', 'question'),
  ('question.12.prompt', 'pt-BR', 'O mercado de ações caiu 30% em 3 meses. Seus amigos dizem que é hora de comprar mais.', 'question'),
  ('question.12.opt.A.text', 'pt-BR', 'Se todos que conheço estão comprando, talvez eles estejam certos', 'question'),
  ('question.12.opt.B.text', 'pt-BR', 'Analiso se a avaliação atual representa uma oportunidade real com base nos fundamentos', 'question'),
  ('question.12.opt.C.text', 'pt-BR', 'Esse nível de incerteza me paralisa, prefiro esperar até estabilizar', 'question'),
  ('question.12.opt.D.text', 'pt-BR', 'Compro agressivamente, quedas são oportunidades e é preciso agir rápido', 'question'),
  ('question.13.prompt', 'pt-BR', 'Você deve escolher entre dois fundos de investimento. Fundo A: rendimento médio de 8%, baixo risco. Fundo B: rendimento médio de 15%, alto risco.', 'question'),
  ('question.13.opt.A.text', 'pt-BR', 'O Fundo B sem dúvida, quero maximizar meu rendimento', 'question'),
  ('question.13.opt.B.text', 'pt-BR', 'Analiso o desvio padrão, o índice Sharpe e o horizonte de cada opção', 'question'),
  ('question.13.opt.C.text', 'pt-BR', 'O Fundo A com certeza, não quero perder o que tenho', 'question'),
  ('question.13.opt.D.text', 'pt-BR', 'Pergunto ao meu banco ou a alguém de confiança qual recomendam', 'question'),
  ('question.14.prompt', 'pt-BR', 'Você tem um investimento em ações que caiu 40% desde que comprou.', 'question'),
  ('question.14.opt.A.text', 'pt-BR', 'Mantenho e compro mais, tenho certeza de que vai se recuperar', 'question'),
  ('question.14.opt.B.text', 'pt-BR', 'Avalio de forma racional se os fundamentos mudaram e decido sem levar em conta meu preço de entrada', 'question'),
  ('question.14.opt.C.text', 'pt-BR', 'Mantenho, mas não compro mais — não consigo assumir a perda vendendo', 'question'),
  ('question.14.opt.D.text', 'pt-BR', 'Pergunto a um broker ou analista o que fazer com essa posição', 'question'),
  ('question.15.prompt', 'pt-BR', 'Você vê que uma ação que gosta está cara segundo seu P/E ratio histórico, mas todos os analistas dizem que vai subir mais.', 'question'),
  ('question.15.opt.A.text', 'pt-BR', 'Se todos os analistas estão otimistas, compro sem esperar', 'question'),
  ('question.15.opt.B.text', 'pt-BR', 'Construo meu próprio modelo de avaliação independente antes de decidir', 'question'),
  ('question.15.opt.C.text', 'pt-BR', 'Se está cara segundo os fundamentos, melhor não entro', 'question'),
  ('question.15.opt.D.text', 'pt-BR', 'Compro agora, o momentum pode durar mais tempo do que o esperado', 'question'),
  ('question.16.prompt', 'pt-BR', 'Você precisa decidir quanto do seu portfólio colocar em ativos internacionais vs. Brasil.', 'question'),
  ('question.16.opt.A.text', 'pt-BR', 'A maioria no Brasil, conheço melhor o mercado local', 'question'),
  ('question.16.opt.B.text', 'pt-BR', 'Analiso correlações, diversificação e expectativas macroeconômicas de cada região', 'question'),
  ('question.16.opt.C.text', 'pt-BR', '50% internacional, há que seguir a tendência global que todos seguem', 'question'),
  ('question.16.opt.D.text', 'pt-BR', 'Maioria internacional, quero exposição agressiva a mercados de alto crescimento', 'question'),
  ('question.17.prompt', 'pt-BR', 'Sua melhor decisão de investimento gerou 80% de rendimento. A que você atribui esse resultado?', 'question'),
  ('question.17.opt.A.text', 'pt-BR', 'Principalmente à minha análise e timing — identifiquei bem a oportunidade', 'question'),
  ('question.17.opt.B.text', 'pt-BR', 'Ao meu processo de pesquisa, embora o mercado também tenha ajudado', 'question'),
  ('question.17.opt.C.text', 'pt-BR', 'Tive sorte, o mercado cooperou mais do que o esperado', 'question'),
  ('question.17.opt.D.text', 'pt-BR', 'Segui o conselho de alguém que sabia mais do que eu', 'question'),
  ('question.18.prompt', 'pt-BR', 'Sua pior decisão de investimento fez você perder 50% do seu capital. O que aconteceu?', 'question'),
  ('question.18.opt.A.text', 'pt-BR', 'O mercado se comportou de maneira impossível de prever — foi má sorte', 'question'),
  ('question.18.opt.B.text', 'pt-BR', 'Cometi um erro na minha análise que devo identificar e corrigir', 'question'),
  ('question.18.opt.C.text', 'pt-BR', 'Me deixei levar pelo pânico no pior momento', 'question'),
  ('question.18.opt.D.text', 'pt-BR', 'Segui o conselho errado de alguém em quem confiei', 'question'),
  ('question.19.prompt', 'pt-BR', 'Você está construindo seu plano de aposentadoria. Tem 30 anos pela frente.', 'question'),
  ('question.19.opt.A.text', 'pt-BR', 'Portfólio 80% renda variável, 20% fixa — há tempo para recuperar perdas', 'question'),
  ('question.19.opt.B.text', 'pt-BR', 'Portfólio otimizado com base na curva de risco decrescente com a idade', 'question'),
  ('question.19.opt.C.text', 'pt-BR', 'Portfólio conservador desde o início, não quero surpresas', 'question'),
  ('question.19.opt.D.text', 'pt-BR', 'Copio a estratégia de algum fundo de pensão reconhecido', 'question'),
  ('question.20.prompt', 'pt-BR', 'Simulador de investimento em aula: você recebe R$ 30.000 virtuais para um mês. Qual é a sua estratégia?', 'question'),
  ('question.20.opt.A.text', 'pt-BR', 'Monto um portfólio diversificado com fundamentals, como se fosse dinheiro real', 'question'),
  ('question.20.opt.B.text', 'pt-BR', 'Coloco a maior parte nas ações mais voláteis, é simulado e quero ganhar', 'question'),
  ('question.20.opt.C.text', 'pt-BR', 'Copio a estratégia de algum fundo reconhecido ou do que o professor sugeriu', 'question'),
  ('question.20.opt.D.text', 'pt-BR', 'Coloco quase tudo em instrumentos seguros como o Tesouro Direto, não quero ver números no vermelho', 'question')
INSERT INTO public.translations (key, lang, text, domain) VALUES
  ('sesgo.contabilidad-mental.name', 'pt-BR', 'Contabilidade Mental', 'sesgo'),
  ('sesgo.contabilidad-mental.definition', 'pt-BR', 'Tratamos quantias de dinheiro de forma diferente dependendo de sua origem ou uso previsto, ignorando que o dinheiro é fungível.', 'sesgo'),
  ('sesgo.contabilidad-mental.description', 'pt-BR', 'A Contabilidade Mental é um viés cognitivo descrito por Richard Thaler (Prêmio Nobel) no qual criamos "contas mentais" separadas para o dinheiro conforme sua fonte ou destino previsto. Isso nos leva a tomar decisões irracionais porque ignoramos o princípio da fungibilidade: um real é um real, independentemente de onde venha.', 'sesgo'),
  ('sesgo.contabilidad-mental.mechanism', 'pt-BR', 'Nosso Sistema 1 (Kahneman) segrega o dinheiro em compartimentos psicológicos: o dinheiro do trabalho é "sagrado", o dinheiro da loteria é "para gastar", o dinheiro do bônus é "extra". Essa segmentação viola a lógica econômica básica.', 'sesgo'),
  ('sesgo.contabilidad-mental.trapQuestion', 'pt-BR', 'Imagine duas situações: (A) Você vai ao cinema, perde uma cédula de R$ 60 na rua. Você compra o ingresso? / (B) Você vai ao cinema, já comprou o ingresso por R$ 60 e o perdeu. Você compra outro? — A maioria responde Sim para A e Não para B. Mas a perda econômica é idêntica nos dois casos.', 'sesgo'),
  ('sesgo.contabilidad-mental.example.0.label', 'pt-BR', 'Investimento', 'sesgo'),
  ('sesgo.contabilidad-mental.example.0.text', 'pt-BR', 'Um investidor perde R$ 1.500 em cripto (conta de "aventuras"), mas mantém intocável seu fundo de emergência. Economicamente é o mesmo dinheiro, mas os trata de forma diferente.', 'sesgo'),
  ('sesgo.contabilidad-mental.example.1.label', 'pt-BR', 'Vida pessoal', 'sesgo'),
  ('sesgo.contabilidad-mental.example.1.text', 'pt-BR', 'Você gasta sem culpa o dinheiro de uma restituição de imposto em algo luxuoso, embora se estivesse na sua conta normal nunca gastaria assim.', 'sesgo'),
  ('sesgo.contabilidad-mental.example.2.label', 'pt-BR', 'Empresa', 'sesgo'),
  ('sesgo.contabilidad-mental.example.2.text', 'pt-BR', 'Uma empresa aloca orçamento por departamento e não o transfere mesmo que outra área precise com mais urgência.', 'sesgo'),
  ('sesgo.contabilidad-mental.antidote.0', 'pt-BR', 'Visualize todo o seu dinheiro como um único fundo — antes de gastar, pergunte-se: eu gastaria isso se viesse do meu salário?', 'sesgo'),
  ('sesgo.contabilidad-mental.antidote.1', 'pt-BR', 'Consolide mentalmente suas contas: avalie o portfólio total, não cada investimento isoladamente.', 'sesgo'),
  ('sesgo.contabilidad-mental.antidote.2', 'pt-BR', 'Regra do "dinheiro extra": qualquer receita inesperada segue as mesmas regras que sua renda normal.', 'sesgo'),
  ('sesgo.contabilidad-mental.antidote.3', 'pt-BR', 'Mantenha um registro unificado de receitas e gastos, sem categorias emocionais.', 'sesgo'),
  ('sesgo.contabilidad-mental.question.0.situation', 'pt-BR', 'Você vai ao cinema. O ingresso custa R$ 60. Ao chegar, percebe que perdeu uma cédula de R$ 60 na rua. Você compra o ingresso mesmo assim?', 'sesgo'),
  ('sesgo.contabilidad-mental.question.0.option.0.text', 'pt-BR', 'Sim, são coisas separadas — perder a cédula não tem relação com o cinema', 'sesgo'),
  ('sesgo.contabilidad-mental.question.0.option.0.reveal', 'pt-BR', 'Racional: correto, o dinheiro é fungível', 'sesgo'),
  ('sesgo.contabilidad-mental.question.0.option.1.text', 'pt-BR', 'Não, já perdi R$ 60, não posso gastar mais R$ 60', 'sesgo'),
  ('sesgo.contabilidad-mental.question.0.option.1.reveal', 'pt-BR', 'Viés: você trata as perdas como vinculadas quando não estão', 'sesgo'),
  ('sesgo.contabilidad-mental.question.1.situation', 'pt-BR', 'Você recebe uma restituição de imposto de R$ 900. Como você trata esse dinheiro?', 'sesgo'),
  ('sesgo.contabilidad-mental.question.1.option.0.text', 'pt-BR', 'Como dinheiro "extra" — me dou um prazer que não me daria com meu salário', 'sesgo'),
  ('sesgo.contabilidad-mental.question.1.option.0.reveal', 'pt-BR', 'Viés: a origem do dinheiro não muda seu valor', 'sesgo'),
  ('sesgo.contabilidad-mental.question.1.option.1.text', 'pt-BR', 'Como qualquer outra renda — vai para onde mais preciso', 'sesgo'),
  ('sesgo.contabilidad-mental.question.1.option.1.reveal', 'pt-BR', 'Racional: correto, a fungibilidade se aplica independentemente da origem', 'sesgo'),
  ('sesgo.contabilidad-mental.question.2.situation', 'pt-BR', 'Seu portfólio tem: Tesouro Direto +5% e uma ação -30%. O Tesouro venceu hoje. O que você faz com esses recursos?', 'sesgo'),
  ('sesgo.contabilidad-mental.question.2.option.0.text', 'pt-BR', 'Reinvisto em Tesouro Direto — não quero misturar com a ação que perdeu', 'sesgo'),
  ('sesgo.contabilidad-mental.question.2.option.0.reveal', 'pt-BR', 'Viés: você trata cada investimento como conta separada em vez de analisar o portfólio total', 'sesgo'),
  ('sesgo.contabilidad-mental.question.2.option.1.text', 'pt-BR', 'Avalio o que tem melhor expectativa de retorno ajustado ao risco hoje', 'sesgo'),
  ('sesgo.contabilidad-mental.question.2.option.1.reveal', 'pt-BR', 'Racional: correto, o portfólio se otimiza em conjunto', 'sesgo'),
  ('sesgo.contabilidad-mental.fixation.0.question', 'pt-BR', 'Por que a contabilidade mental é um viés e não um sistema racional?', 'sesgo'),
  ('sesgo.contabilidad-mental.fixation.0.option.0', 'pt-BR', 'Porque trata o dinheiro de forma diferente conforme sua origem, quando na realidade R$ 1 sempre vale R$ 1', 'sesgo'),
  ('sesgo.contabilidad-mental.fixation.0.option.1', 'pt-BR', 'Porque faz com que gastemos menos do que deveríamos', 'sesgo'),
  ('sesgo.contabilidad-mental.fixation.0.option.2', 'pt-BR', 'Porque afeta apenas pessoas com pouco conhecimento financeiro', 'sesgo'),
  ('sesgo.contabilidad-mental.fixation.1.question', 'pt-BR', 'Você ganha R$ 150 no cassino e os gasta em roupas que normalmente não compraria. Que viés explica isso?', 'sesgo'),
  ('sesgo.contabilidad-mental.fixation.1.option.0', 'pt-BR', 'Contabilidade mental: você criou uma conta de dinheiro ganho que sente livre para gastar', 'sesgo'),
  ('sesgo.contabilidad-mental.fixation.1.option.1', 'pt-BR', 'Excesso de confiança: você acredita que continuará ganhando', 'sesgo'),
  ('sesgo.contabilidad-mental.fixation.1.option.2', 'pt-BR', 'Efeito manada: todo mundo gasta quando ganha no cassino', 'sesgo'),
  ('sesgo.contabilidad-mental.fixation.2.question', 'pt-BR', 'Qual é a implicação financeira mais perigosa da contabilidade mental?', 'sesgo'),
  ('sesgo.contabilidad-mental.fixation.2.option.0', 'pt-BR', 'Que podemos ter dívidas com juros altos e poupança ao mesmo tempo sem perceber a contradição', 'sesgo'),
  ('sesgo.contabilidad-mental.fixation.2.option.1', 'pt-BR', 'Que nos faz poupar demais em contas separadas', 'sesgo'),
  ('sesgo.contabilidad-mental.fixation.2.option.2', 'pt-BR', 'Que nos impede de investir em mais de um instrumento ao mesmo tempo', 'sesgo'),
  ('sesgo.confirmation-bias.name', 'pt-BR', 'Viés de Confirmação', 'sesgo'),
  ('sesgo.confirmation-bias.definition', 'pt-BR', 'Buscamos, notamos e lembramos a informação que confirma nossas crenças anteriores, ignorando a que as contradiz.', 'sesgo'),
  ('sesgo.confirmation-bias.description', 'pt-BR', 'O Viés de Confirmação é um dos vieses mais perniciosos nas finanças. Segundo o CFA Institute, pertence à subcategoria de Perseverança de Crenças: nos recusamos a atualizar nossas opiniões mesmo quando os dados apontam em outra direção. Não é má-fé — é que o Sistema 1 constrói histórias coerentes, não precisas.', 'sesgo'),
  ('sesgo.confirmation-bias.mechanism', 'pt-BR', 'Daniel Kahneman explica que o Sistema 1 opera sob o WYSIATI ("What You See Is All There Is"): constrói a melhor história possível com as informações disponíveis, ignorando o que falta. A dissonância cognitiva torna doloroso enfrentar evidências contraditórias.', 'sesgo'),
  ('sesgo.confirmation-bias.trapQuestion', 'pt-BR', 'Você está convicto de que o Bitcoin vai subir. O que você busca no Google? A) "Razões pelas quais o Bitcoin vai subir" ou B) "Riscos de investir em Bitcoin hoje". — A maioria escolhe A, buscando validar, não questionar.', 'sesgo'),
  ('sesgo.confirmation-bias.example.0.label', 'pt-BR', 'Investimento', 'sesgo'),
  ('sesgo.confirmation-bias.example.0.text', 'pt-BR', 'Você está convicto de que a Tesla vai subir. Lê apenas artigos otimistas e ignora os que questionam sua avaliação. Sua "pesquisa" é, na verdade, validação.', 'sesgo'),
  ('sesgo.confirmation-bias.example.1.label', 'pt-BR', 'Decisão pessoal', 'sesgo'),
  ('sesgo.confirmation-bias.example.1.text', 'pt-BR', 'Você decide que determinada cidade é perfeita para morar. Lembra das boas notícias sobre ela e esquece as ruins.', 'sesgo'),
  ('sesgo.confirmation-bias.example.2.label', 'pt-BR', 'Empresa', 'sesgo'),
  ('sesgo.confirmation-bias.example.2.text', 'pt-BR', 'Um CEO comprometido com uma estratégia ignora métricas que a questionam e enfatiza as que a apoiam em seus relatórios trimestrais.', 'sesgo'),
  ('sesgo.confirmation-bias.antidote.0', 'pt-BR', 'Pratique o "empirismo negativo": tente provar que sua ideia é FALSA, não que é verdadeira.', 'sesgo'),
  ('sesgo.confirmation-bias.antidote.1', 'pt-BR', 'Steel-manning: construa o melhor argumento possível contra a sua tese antes de agir.', 'sesgo'),
  ('sesgo.confirmation-bias.antidote.2', 'pt-BR', 'Busque ativamente artigos, analistas e dados que contradigam sua posição.', 'sesgo'),
  ('sesgo.confirmation-bias.antidote.3', 'pt-BR', 'Antes de qualquer investimento, escreva explicitamente: o que precisaria acontecer para que eu esteja errado?', 'sesgo'),
  ('sesgo.confirmation-bias.question.0.situation', 'pt-BR', 'Você está convicto de que uma ação vai subir. O que você busca no Google?', 'sesgo'),
  ('sesgo.confirmation-bias.question.0.option.0.text', 'pt-BR', 'Razões pelas quais a ação vai subir', 'sesgo'),
  ('sesgo.confirmation-bias.question.0.option.0.reveal', 'pt-BR', 'Viés: você está procurando validar, não investigar', 'sesgo'),
  ('sesgo.confirmation-bias.question.0.option.1.text', 'pt-BR', 'Riscos e argumentos contra esse investimento', 'sesgo'),
  ('sesgo.confirmation-bias.question.0.option.1.reveal', 'pt-BR', 'Racional: primeiro busque a hipótese nula — por que você pode estar errado', 'sesgo'),
  ('sesgo.confirmation-bias.question.1.situation', 'pt-BR', 'Um político de quem você não gosta faz uma grande doação para a caridade. Qual é seu primeiro pensamento?', 'sesgo'),
  ('sesgo.confirmation-bias.question.1.option.0.text', 'pt-BR', 'Com certeza está fazendo isso para sonegar impostos ou limpar sua imagem', 'sesgo'),
  ('sesgo.confirmation-bias.question.1.option.0.reveal', 'pt-BR', 'Viés: interpretamos a mesma evidência de forma diferente conforme nossas crenças anteriores', 'sesgo'),
  ('sesgo.confirmation-bias.question.1.option.1.text', 'pt-BR', 'Dessa vez fez algo bom, independentemente das motivações', 'sesgo'),
  ('sesgo.confirmation-bias.question.1.option.1.reveal', 'pt-BR', 'Racional: separamos os fatos dos nossos preconceitos anteriores', 'sesgo'),
  ('sesgo.confirmation-bias.question.2.situation', 'pt-BR', 'Você está há 6 meses investindo em uma empresa que não deu resultados. Encontra um artigo dizendo que o CEO é brilhante.', 'sesgo'),
  ('sesgo.confirmation-bias.question.2.option.0.text', 'pt-BR', 'Isso confirma que minha análise estava certa — vale esperar mais', 'sesgo'),
  ('sesgo.confirmation-bias.question.2.option.0.reveal', 'pt-BR', 'Viés: você usa informação nova para reforçar uma posição que talvez devesse ser revisada', 'sesgo'),
  ('sesgo.confirmation-bias.question.2.option.1.text', 'pt-BR', 'Interessante, mas também vou buscar artigos críticos sobre o CEO antes de decidir', 'sesgo'),
  ('sesgo.confirmation-bias.question.2.option.1.reveal', 'pt-BR', 'Racional: o novo dado é avaliado junto a todas as evidências disponíveis', 'sesgo'),
  ('sesgo.confirmation-bias.fixation.0.question', 'pt-BR', 'O que exatamente faz o viés de confirmação?', 'sesgo'),
  ('sesgo.confirmation-bias.fixation.0.option.0', 'pt-BR', 'Buscar, interpretar e lembrar informações que confirmam o que já acreditamos, ignorando o que as contradiz', 'sesgo'),
  ('sesgo.confirmation-bias.fixation.0.option.1', 'pt-BR', 'Confirmar decisões passadas independentemente de terem sido corretas ou não', 'sesgo'),
  ('sesgo.confirmation-bias.fixation.0.option.2', 'pt-BR', 'Seguir a opinião da maioria para confirmar que nossa decisão está certa', 'sesgo'),
  ('sesgo.confirmation-bias.fixation.1.question', 'pt-BR', 'Um investidor convicto de que uma empresa é excelente lê apenas análises positivas. Qual é o risco concreto?', 'sesgo'),
  ('sesgo.confirmation-bias.fixation.1.option.0', 'pt-BR', 'Perder sinais de alerta reais porque evita ativamente informações negativas', 'sesgo'),
  ('sesgo.confirmation-bias.fixation.1.option.1', 'pt-BR', 'Superestimar o risco por ter informação demais sobre a empresa', 'sesgo'),
  ('sesgo.confirmation-bias.fixation.1.option.2', 'pt-BR', 'Seguir o efeito manada ao ler as mesmas análises que todo mundo', 'sesgo'),
  ('sesgo.confirmation-bias.fixation.2.question', 'pt-BR', 'Qual é o antídoto mais eficaz contra o viés de confirmação?', 'sesgo'),
  ('sesgo.confirmation-bias.fixation.2.option.0', 'pt-BR', 'Buscar ativamente o melhor argumento contrário à sua própria tese antes de decidir', 'sesgo'),
  ('sesgo.confirmation-bias.fixation.2.option.1', 'pt-BR', 'Ler mais fontes de informação para ter uma visão mais completa', 'sesgo'),
  ('sesgo.confirmation-bias.fixation.2.option.2', 'pt-BR', 'Esperar que outros tomem a decisão primeiro para validar sua análise', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.name', 'pt-BR', 'Disponibilidade e Representatividade', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.definition', 'pt-BR', 'Julgamos probabilidades pela facilidade com que lembramos exemplos (disponibilidade) ou pela categoria a que algo se assemelha (representatividade).', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.description', 'pt-BR', 'Essas duas heurísticas são atalhos mentais do Sistema 1. A Disponibilidade nos leva a superestimar a frequência de eventos memoráveis ou recentes. A Representatividade nos faz classificar situações por estereótipos, ignorando probabilidades estatísticas reais.', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.mechanism', 'pt-BR', 'Quando enfrentamos uma pergunta difícil (qual é a probabilidade de X?), o cérebro a substitui por uma mais fácil: o quanto me é fácil lembrar exemplos de X? ou a qual categoria X se parece? Essas substituições são rápidas, mas sistematicamente equivocadas.', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.trapQuestion', 'pt-BR', 'Linda tem 31 anos, é muito inteligente e ativista social. O que é mais provável? A) Caixa de banco. B) Caixa de banco e feminista. — A maioria escolhe B, embora matematicamente A seja sempre mais provável do que A+B.', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.example.0.label', 'pt-BR', 'Disponibilidade', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.example.0.text', 'pt-BR', 'Após ver notícias sobre um assalto, você acredita que a criminalidade aumentou drasticamente, embora estatisticamente tenha diminuído. O que é memorável distorce sua percepção de frequência.', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.example.1.label', 'pt-BR', 'Representatividade', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.example.1.text', 'pt-BR', 'Você vê uma empresa jovem com fundador carismático e tecnologia da moda — parece com a Apple em 1997. Você investe sem revisar seus fundamentals. A semelhança não é suficiente.', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.example.2.label', 'pt-BR', 'Investimento', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.example.2.text', 'pt-BR', 'Após três meses de mercado em alta, você acredita que o rally vai continuar (disponibilidade recente). Após um crash, acredita que tudo continuará caindo.', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.antidote.0', 'pt-BR', 'Antes de estimar uma probabilidade, pergunte: qual é a taxa base estatística real?', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.antidote.1', 'pt-BR', 'Desconfie da sua primeira impressão quando algo "se parece" com um padrão de sucesso.', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.antidote.2', 'pt-BR', 'Eventos dramáticos ou recentes não são mais prováveis — apenas mais memoráveis.', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.antidote.3', 'pt-BR', 'Busque dados concretos antes de agir com base em uma intuição fundada no que você "lembra".', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.question.0.situation', 'pt-BR', 'O que causa mais mortes por ano no Brasil?', 'sesgo')
INSERT INTO public.translations (key, lang, text, domain) VALUES
  ('sesgo.disponibilidad-representatividad.question.0.option.0.text', 'pt-BR', 'Homicídios', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.question.0.option.0.reveal', 'pt-BR', 'Viés de disponibilidade: homicídios aparecem mais nas notícias, parecem mais frequentes', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.question.0.option.1.text', 'pt-BR', 'Diabetes e doenças crônicas', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.question.0.option.1.reveal', 'pt-BR', 'Racional: doenças crônicas causam 5 a 10 vezes mais mortes, mas são menos "disponíveis" na memória', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.question.1.situation', 'pt-BR', 'Linda tem 31 anos, é inteligente e foi ativista. O que é mais provável que ela seja hoje?', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.question.1.option.0.text', 'pt-BR', 'Caixa de banco e feminista ativa', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.question.1.option.0.reveal', 'pt-BR', 'Viés de representatividade (Falácia da Conjunção): dois eventos juntos nunca podem ser mais prováveis do que um só', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.question.1.option.1.text', 'pt-BR', 'Caixa de banco', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.question.1.option.1.reveal', 'pt-BR', 'Racional: P(A) é sempre ≥ P(A e B). O estereótipo nos distrai da lógica básica', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.question.2.situation', 'pt-BR', 'Uma moeda justa cai cara 5 vezes seguidas. O que você espera no lançamento 6?', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.question.2.option.0.text', 'pt-BR', 'Coroa é mais provável — já está "na hora" de sair', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.question.2.option.0.reveal', 'pt-BR', 'Falácia do jogador: cada lançamento é independente. O passado não influencia o futuro', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.question.2.option.1.text', 'pt-BR', '50/50 — cada lançamento é independente do anterior', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.question.2.option.1.reveal', 'pt-BR', 'Racional: a moeda não tem memória. A representatividade nos faz ver padrões onde não existem', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.fixation.0.question', 'pt-BR', 'O que determina o quão provável nos parece um evento segundo o viés de disponibilidade?', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.fixation.0.option.0', 'pt-BR', 'A facilidade com que exemplos desse evento vêm à nossa mente', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.fixation.0.option.1', 'pt-BR', 'A frequência estatística real com que esse evento ocorre', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.fixation.0.option.2', 'pt-BR', 'A quantidade de informação que temos sobre esse evento', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.fixation.1.question', 'pt-BR', 'Após ver notícias sobre acidentes aéreos, muitas pessoas preferem dirigir. O que explica essa decisão?', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.fixation.1.option.0', 'pt-BR', 'A imagem vívida do acidente faz o voo parecer mais perigoso do que estatisticamente é', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.fixation.1.option.1', 'pt-BR', 'Dirigir é objetivamente mais seguro do que voar em todos os contextos', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.fixation.1.option.2', 'pt-BR', 'As pessoas fazem uma análise racional do risco baseada nas notícias', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.fixation.2.question', 'pt-BR', 'Qual é o impacto do viés de disponibilidade nas decisões de investimento?', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.fixation.2.option.0', 'pt-BR', 'Sobreponderar ativos que estiveram nas notícias recentemente, independentemente de seus fundamentos', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.fixation.2.option.1', 'pt-BR', 'Diversificar demais o portfólio por medo de eventos pouco prováveis', 'sesgo'),
  ('sesgo.disponibilidad-representatividad.fixation.2.option.2', 'pt-BR', 'Ignorar completamente os eventos recentes ao tomar decisões', 'sesgo'),
  ('sesgo.overconfidence.name', 'pt-BR', 'Excesso de Confiança', 'sesgo'),
  ('sesgo.overconfidence.definition', 'pt-BR', 'Temos uma confiança injustificada em nosso próprio raciocínio, julgamentos e habilidades cognitivas.', 'sesgo'),
  ('sesgo.overconfidence.description', 'pt-BR', 'Kahneman afirma que, se tivesse uma varinha mágica para eliminar um único viés, eliminaria o excesso de confiança, pois ele amplifica quase todos os outros. Ele se manifesta como Ilusão de Conhecimento (acreditar que mais informação gera mais precisão) e Ilusão de Controle (acreditar que podemos influenciar o aleatório).', 'sesgo'),
  ('sesgo.overconfidence.mechanism', 'pt-BR', 'O Sistema 1 constrói histórias coerentes com as informações disponíveis. Como a história é coerente, ela nos parece verdadeira e confiável. Não paramos para perguntar quais dados nos faltam — a confiança não vem da evidência, mas da coerência da narrativa.', 'sesgo'),
  ('sesgo.overconfidence.trapQuestion', 'pt-BR', 'Em comparação com a média do seu grupo, como você avaliaria sua capacidade de tomar decisões financeiras? A) Acima da média. B) Média ou abaixo. — Em grupos instruídos, 70 a 80% escolhe A, embora estatisticamente seja impossível.', 'sesgo'),
  ('sesgo.overconfidence.example.0.label', 'pt-BR', 'Investimento', 'sesgo'),
  ('sesgo.overconfidence.example.0.text', 'pt-BR', 'Um estudo da Duke descobriu que os CFOs de empresas fornecem intervalos de confiança de 80% para o S&P500 que falham 67% das vezes. Preferem parecer precisos mesmo quando estão errados.', 'sesgo'),
  ('sesgo.overconfidence.example.1.label', 'pt-BR', 'Trading', 'sesgo'),
  ('sesgo.overconfidence.example.1.text', 'pt-BR', 'Os investidores individuais que operam mais ativamente obtêm rendimentos menores do que os passivos — a atividade excessiva é sinal de excesso de confiança.', 'sesgo'),
  ('sesgo.overconfidence.example.2.label', 'pt-BR', 'Pessoal', 'sesgo'),
  ('sesgo.overconfidence.example.2.text', 'pt-BR', '80% das pessoas acreditam que suas habilidades de direção estão acima da média. 93% dos estudantes universitários acredita estar na metade superior de sua turma.', 'sesgo'),
  ('sesgo.overconfidence.antidote.0', 'pt-BR', 'Mantenha um diário de decisões: registre suas previsões e meça sua precisão real versus percebida.', 'sesgo'),
  ('sesgo.overconfidence.antidote.1', 'pt-BR', 'Pratique intervalos de incerteza amplos: se 90% das suas estimativas estão dentro do intervalo, o intervalo está correto.', 'sesgo'),
  ('sesgo.overconfidence.antidote.2', 'pt-BR', 'O teste da "Outside View": qual é a taxa base de sucesso para situações semelhantes à sua?', 'sesgo'),
  ('sesgo.overconfidence.antidote.3', 'pt-BR', 'Busque ativamente quem sabe mais do que você sobre esse tema — não como sinal de fraqueza, mas de inteligência.', 'sesgo'),
  ('sesgo.overconfidence.question.0.situation', 'pt-BR', 'Comparado ao seu grupo, como você avaliaria sua capacidade de tomar decisões financeiras racionais?', 'sesgo'),
  ('sesgo.overconfidence.question.0.option.0.text', 'pt-BR', 'Acima da média (top 50%)', 'sesgo'),
  ('sesgo.overconfidence.question.0.option.0.reveal', 'pt-BR', 'Viés: estatisticamente, metade do grupo está abaixo. Se quase todos escolhem isso, algo não fecha', 'sesgo'),
  ('sesgo.overconfidence.question.0.option.1.text', 'pt-BR', 'Média ou abaixo da média', 'sesgo'),
  ('sesgo.overconfidence.question.0.option.1.reveal', 'pt-BR', 'Racional: a humildade epistêmica — saber o que você não sabe — é a base de boas decisões', 'sesgo'),
  ('sesgo.overconfidence.question.1.situation', 'pt-BR', 'Você investe há 3 anos com bons rendimentos. A que você atribui isso?', 'sesgo'),
  ('sesgo.overconfidence.question.1.option.0.text', 'pt-BR', 'Minha estratégia e análise — tomei as decisões certas', 'sesgo'),
  ('sesgo.overconfidence.question.1.option.0.reveal', 'pt-BR', 'Possível viés de autoatribuição: mercados em alta fazem todos parecerem gênios', 'sesgo'),
  ('sesgo.overconfidence.question.1.option.1.text', 'pt-BR', 'Uma combinação de processo sólido e condições favoráveis de mercado', 'sesgo'),
  ('sesgo.overconfidence.question.1.option.1.reveal', 'pt-BR', 'Racional: separar habilidade de sorte exige um horizonte longo e uma análise honesta', 'sesgo'),
  ('sesgo.overconfidence.question.2.situation', 'pt-BR', 'O S&P500 está em 5.000. Sua estimativa para 12 meses com 90% de confiança seria:', 'sesgo'),
  ('sesgo.overconfidence.question.2.option.0.text', 'pt-BR', '4.800 – 5.300 (intervalo preciso)', 'sesgo'),
  ('sesgo.overconfidence.question.2.option.0.reveal', 'pt-BR', 'Viés: intervalos estreitos falham em mais de 60% das vezes em estudos com especialistas', 'sesgo'),
  ('sesgo.overconfidence.question.2.option.1.text', 'pt-BR', '3.500 – 6.500 (intervalo amplo)', 'sesgo'),
  ('sesgo.overconfidence.question.2.option.1.reveal', 'pt-BR', 'Racional: 90% de confiança real exige um intervalo muito mais amplo em sistemas complexos', 'sesgo'),
  ('sesgo.overconfidence.fixation.0.question', 'pt-BR', 'Qual é a diferença entre excesso de confiança e ilusão de conhecimento?', 'sesgo'),
  ('sesgo.overconfidence.fixation.0.option.0', 'pt-BR', 'A ilusão de conhecimento é acreditar que mais informação nos torna mais precisos, mesmo que essa informação seja irrelevante', 'sesgo'),
  ('sesgo.overconfidence.fixation.0.option.1', 'pt-BR', 'São exatamente a mesma coisa: ambos descrevem superestimar as próprias habilidades', 'sesgo'),
  ('sesgo.overconfidence.fixation.0.option.2', 'pt-BR', 'O excesso de confiança se aplica apenas a especialistas; a ilusão de conhecimento, a iniciantes', 'sesgo'),
  ('sesgo.overconfidence.fixation.1.question', 'pt-BR', 'Um trader analisa 20 indicadores antes de cada operação, acreditando que por isso suas previsões são mais precisas. Que viés isso ilustra?', 'sesgo'),
  ('sesgo.overconfidence.fixation.1.option.0', 'pt-BR', 'Ilusão de conhecimento: mais dados não garantem melhores previsões se não acrescentam informação real', 'sesgo'),
  ('sesgo.overconfidence.fixation.1.option.1', 'pt-BR', 'Viés de confirmação: busca indicadores que confirmem sua decisão prévia', 'sesgo'),
  ('sesgo.overconfidence.fixation.1.option.2', 'pt-BR', 'Efeito halo: os indicadores sofisticados lhe dão uma imagem de especialista', 'sesgo'),
  ('sesgo.overconfidence.fixation.2.question', 'pt-BR', 'O que é o viés de autoatribuição e como ele se relaciona com o excesso de confiança?', 'sesgo'),
  ('sesgo.overconfidence.fixation.2.option.0', 'pt-BR', 'Atribuir os sucessos à própria habilidade e os fracassos a fatores externos, reforçando a confiança sem fundamento real', 'sesgo'),
  ('sesgo.overconfidence.fixation.2.option.1', 'pt-BR', 'Acreditar que nossas habilidades são superiores às da média em todas as áreas', 'sesgo'),
  ('sesgo.overconfidence.fixation.2.option.2', 'pt-BR', 'Confiar demais nas recomendações de outros sem analisá-las', 'sesgo'),
  ('sesgo.self-attribution.name', 'pt-BR', 'Autoatribuição', 'sesgo'),
  ('sesgo.self-attribution.definition', 'pt-BR', 'Atribuímos nossos sucessos à nossa habilidade e nossos fracassos a fatores externos.', 'sesgo'),
  ('sesgo.self-attribution.description', 'pt-BR', 'A Autoatribuição é o "combustível" do Excesso de Confiança. Juntos formam um ciclo perigoso: ganho → foi minha habilidade → aprendo que sou bom → perco → foi má sorte → não aprendo nada. Esse ciclo destrói nossa capacidade de calibrar o risco real.', 'sesgo'),
  ('sesgo.self-attribution.mechanism', 'pt-BR', 'O mecanismo é defensivo: o ego precisa proteger uma autoimagem positiva. Atribuir a si mesmo o mérito dos sucessos alimenta a autoestima; culpar o ambiente pelos fracassos protege da autocrítica. O resultado é que nunca aprendemos com nossos erros de forma sistemática.', 'sesgo'),
  ('sesgo.self-attribution.trapQuestion', 'pt-BR', 'Sua carteira subiu +25% este ano. Qual foi o fator principal? A) Minha estratégia e seleção (habilidade). B) Estive no setor certo no momento certo (sorte). — A maioria escolhe A. E se a carteira tivesse caído -25%?', 'sesgo'),
  ('sesgo.self-attribution.example.0.label', 'pt-BR', 'Investimento', 'sesgo'),
  ('sesgo.self-attribution.example.0.text', 'pt-BR', 'Sua carteira subiu 40% em 2021. Foi sua análise brilhante. Em 2022 caiu 30%. Foi o Fed, o mercado, a guerra na Ucrânia. O duplo padrão impede o aprendizado real.', 'sesgo'),
  ('sesgo.self-attribution.example.1.label', 'pt-BR', 'Empresa', 'sesgo'),
  ('sesgo.self-attribution.example.1.text', 'pt-BR', 'Um CEO reporta ganhos recordes: "nossa estratégia brilhante." Reporta prejuízos: "condições macroeconômicas adversas sem precedentes."', 'sesgo'),
  ('sesgo.self-attribution.example.2.label', 'pt-BR', 'Pessoal', 'sesgo'),
  ('sesgo.self-attribution.example.2.text', 'pt-BR', 'Você passou em uma prova: estudou bem. Reprovou: o professor foi injusto ou as questões eram ambíguas.', 'sesgo'),
  ('sesgo.self-attribution.antidote.0', 'pt-BR', 'Diário de decisões: registre ANTES de investir o seu raciocínio. Ao revisar, avalie o processo, não apenas o resultado.', 'sesgo'),
  ('sesgo.self-attribution.antidote.1', 'pt-BR', 'Separar processo de resultado: foi uma boa decisão dado o que você sabia naquele momento, independentemente do resultado?', 'sesgo'),
  ('sesgo.self-attribution.antidote.2', 'pt-BR', 'Pós-mortem honesto: quando um investimento der errado, identifique exatamente qual erro você cometeu — não qual fator externo falhou.', 'sesgo'),
  ('sesgo.self-attribution.antidote.3', 'pt-BR', 'Compartilhe suas análises com alguém crítico antes de agir — a exposição reduz a autoilusão.', 'sesgo'),
  ('sesgo.self-attribution.question.0.situation', 'pt-BR', 'Seu principal investimento subiu 35% este ano. A que você atribui principalmente?', 'sesgo'),
  ('sesgo.self-attribution.question.0.option.0.text', 'pt-BR', 'Minha análise e timing — identifiquei bem a oportunidade', 'sesgo'),
  ('sesgo.self-attribution.question.0.option.0.reveal', 'pt-BR', 'Viés de autoatribuição (Self-Enhancement): pode ter sido habilidade, mas você verificou que não foi sorte de mercado?', 'sesgo'),
  ('sesgo.self-attribution.question.0.option.1.text', 'pt-BR', 'Uma combinação de análise razoável e condições favoráveis', 'sesgo'),
  ('sesgo.self-attribution.question.0.option.1.reveal', 'pt-BR', 'Racional: distinguir habilidade de sorte exige múltiplos ciclos de mercado, não apenas um ano', 'sesgo'),
  ('sesgo.self-attribution.question.1.situation', 'pt-BR', 'Seu principal investimento caiu 25% de forma inesperada. Como você descreve isso na sua análise?', 'sesgo'),
  ('sesgo.self-attribution.question.1.option.0.text', 'pt-BR', 'Risco sistêmico / evento imprevisível — foi externo à minha análise', 'sesgo'),
  ('sesgo.self-attribution.question.1.option.0.reveal', 'pt-BR', 'Viés de autoproteção: era realmente imprevisível ou você ignorou sinais que não queria ver?', 'sesgo'),
  ('sesgo.self-attribution.question.1.option.1.text', 'pt-BR', 'Erro de análise — preciso identificar o que não enxerguei corretamente', 'sesgo'),
  ('sesgo.self-attribution.question.1.option.1.reveal', 'pt-BR', 'Racional: mesmo que o choque tenha sido externo, o dimensionamento do risco estava correto?', 'sesgo'),
  ('sesgo.self-attribution.question.2.situation', 'pt-BR', 'Um colega dobrou seu investimento em criptomoedas este ano. O que você pensa?', 'sesgo'),
  ('sesgo.self-attribution.question.2.option.0.text', 'pt-BR', 'É um investidor habilidoso que soube identificar a oportunidade', 'sesgo'),
  ('sesgo.self-attribution.question.2.option.0.reveal', 'pt-BR', 'Duplo padrão: se fosse sua perda, também seria habilidade? Aplicamos critérios diferentes para os sucessos alheios e os próprios', 'sesgo'),
  ('sesgo.self-attribution.question.2.option.1.text', 'pt-BR', 'Assumiu riscos altos e as condições o favoreceram', 'sesgo'),
  ('sesgo.self-attribution.question.2.option.1.reveal', 'pt-BR', 'Racional: consistência no critério — aplique o mesmo padrão a você e aos outros', 'sesgo'),
  ('sesgo.self-attribution.fixation.0.question', 'pt-BR', 'O que é a aversão à perda segundo Kahneman e Tversky?', 'sesgo'),
  ('sesgo.self-attribution.fixation.0.option.0', 'pt-BR', 'Perder R$ 100 dói aproximadamente o dobro do prazer de ganhar R$ 100', 'sesgo')
INSERT INTO public.translations (key, lang, text, domain) VALUES
  ('sesgo.self-attribution.fixation.0.option.1', 'pt-BR', 'Preferir sempre os investimentos mais seguros independentemente do retorno', 'sesgo'),
  ('sesgo.self-attribution.fixation.0.option.2', 'pt-BR', 'Evitar qualquer decisão que possa resultar em perda', 'sesgo'),
  ('sesgo.self-attribution.fixation.1.question', 'pt-BR', 'Um investidor mantém uma ação que caiu 40% esperando se recuperar, mas vende rapidamente as que sobem. Como se chama esse padrão?', 'sesgo'),
  ('sesgo.self-attribution.fixation.1.option.0', 'pt-BR', 'Efeito disposição: vender as vencedoras cedo e manter as perdedoras por tempo demais', 'sesgo'),
  ('sesgo.self-attribution.fixation.1.option.1', 'pt-BR', 'Viés de confirmação: busca informações que justifiquem manter a ação', 'sesgo'),
  ('sesgo.self-attribution.fixation.1.option.2', 'pt-BR', 'Excesso de confiança: acredita que pode prever quando vai se recuperar', 'sesgo'),
  ('sesgo.self-attribution.fixation.2.question', 'pt-BR', 'O que é a aversão míope à perda?', 'sesgo'),
  ('sesgo.self-attribution.fixation.2.option.0', 'pt-BR', 'Revisar o portfólio com tanta frequência que as perdas de curto prazo dominam as decisões de longo prazo', 'sesgo'),
  ('sesgo.self-attribution.fixation.2.option.1', 'pt-BR', 'Recusar-se a investir em ativos que já tiveram perdas históricas', 'sesgo'),
  ('sesgo.self-attribution.fixation.2.option.2', 'pt-BR', 'Preferir instrumentos de renda fixa acima de qualquer outro ativo', 'sesgo'),
  ('sesgo.status-quo.name', 'pt-BR', 'Viés de Status Quo', 'sesgo'),
  ('sesgo.status-quo.definition', 'pt-BR', 'Preferimos manter as coisas como estão, mesmo quando mudar seria objetivamente melhor.', 'sesgo'),
  ('sesgo.status-quo.description', 'pt-BR', 'Descrito por Samuelson e Zeckhauser (1988), esse viés surge do conforto do familiar e do medo do arrependimento. A inércia psicológica é poderosa: sair do estado atual implica o risco de errar ativamente, enquanto ficar parado se percebe como "não fazer nada de errado".', 'sesgo'),
  ('sesgo.status-quo.mechanism', 'pt-BR', 'O Sistema 1 avalia opções em relação a um ponto de referência neutro — o Status Quo. Como as perdas pesam o dobro dos ganhos (Aversão à Perda), qualquer mudança é percebida como potencialmente desvantajosa. A preguiça do Sistema 2 completa o quadro.', 'sesgo'),
  ('sesgo.status-quo.trapQuestion', 'pt-BR', 'Oferecem a você trocar sua carteira atual por uma com melhores expectativas de retorno, mas isso exige uma ação ativa. Você faz? — A maioria diz que sim em tese. Na prática, a inércia vence.', 'sesgo'),
  ('sesgo.status-quo.example.0.label', 'pt-BR', 'Previdência', 'sesgo'),
  ('sesgo.status-quo.example.0.text', 'pt-BR', 'Quando o plano de previdência de uma empresa muda de opt-in para opt-out, a participação sobe de 40% para 90%. O padrão é tudo.', 'sesgo'),
  ('sesgo.status-quo.example.1.label', 'pt-BR', 'Investimento', 'sesgo'),
  ('sesgo.status-quo.example.1.text', 'pt-BR', 'Um investidor herda uma carteira de títulos do pai. Embora ações tivessem melhor retorno esperado, ele mantém os títulos porque "era o que havia".', 'sesgo'),
  ('sesgo.status-quo.example.2.label', 'pt-BR', 'Empresa', 'sesgo'),
  ('sesgo.status-quo.example.2.text', 'pt-BR', 'Uma empresa continua usando o mesmo fornecedor de software por 10 anos, mesmo havendo opções melhores e mais baratas, simplesmente porque "sempre foi assim".', 'sesgo'),
  ('sesgo.status-quo.antidote.0', 'pt-BR', 'Reencadre a decisão: "Eu escolheria este portfólio se estivesse começando do zero hoje?"', 'sesgo'),
  ('sesgo.status-quo.antidote.1', 'pt-BR', 'Estabeleça revisões periódicas obrigatórias — a inércia vence se não houver um gatilho externo.', 'sesgo'),
  ('sesgo.status-quo.antidote.2', 'pt-BR', 'Separe o apego emocional da análise financeira: herança, tradição e hábito não são argumentos financeiros.', 'sesgo'),
  ('sesgo.status-quo.antidote.3', 'pt-BR', 'O teste da ação inversa: se hoje você tivesse o que quer mudar, mudaria para o que tem agora?', 'sesgo'),
  ('sesgo.status-quo.question.0.situation', 'pt-BR', 'Você está há 5 anos com o mesmo fundo de investimento. Surge um novo com melhor histórico ajustado ao risco. O que você faz?', 'sesgo'),
  ('sesgo.status-quo.question.0.option.0.text', 'pt-BR', 'Fico com o meu — já conheço e mudar dá preguiça', 'sesgo'),
  ('sesgo.status-quo.question.0.option.0.reveal', 'pt-BR', 'Viés de status quo: a inércia e o conforto do familiar impedem a decisão ótima', 'sesgo'),
  ('sesgo.status-quo.question.0.option.1.text', 'pt-BR', 'Avalio os dois com os mesmos critérios e escolho o melhor, não importa qual eu tinha antes', 'sesgo'),
  ('sesgo.status-quo.question.0.option.1.reveal', 'pt-BR', 'Racional: a decisão se toma com os dados atuais, não com o peso do que você já tem', 'sesgo'),
  ('sesgo.status-quo.question.1.situation', 'pt-BR', 'Você herdou uma carteira de títulos conservadores do seu avô. Ações teriam melhor retorno esperado para seu horizonte de 30 anos. O que você faz?', 'sesgo'),
  ('sesgo.status-quo.question.1.option.0.text', 'pt-BR', 'Mantenho como está — foi a escolha dele e mudar parece errado', 'sesgo'),
  ('sesgo.status-quo.question.1.option.0.reveal', 'pt-BR', 'Viés de status quo + efeito dotação: o apego à origem da carteira paralisa a otimização', 'sesgo'),
  ('sesgo.status-quo.question.1.option.1.text', 'pt-BR', 'Avalio se essa carteira é adequada para MEU horizonte e perfil, independentemente de sua história', 'sesgo'),
  ('sesgo.status-quo.question.1.option.1.reveal', 'pt-BR', 'Racional: a origem da carteira não determina sua adequação para a sua situação atual', 'sesgo'),
  ('sesgo.status-quo.question.2.situation', 'pt-BR', 'Seu banco cobra R$ 350/ano em tarifas. Outro banco oferece as mesmas condições sem tarifa. O que você faz?', 'sesgo'),
  ('sesgo.status-quo.question.2.option.0.text', 'pt-BR', 'Fico — mudar de banco é um processo tedioso', 'sesgo'),
  ('sesgo.status-quo.question.2.option.0.reveal', 'pt-BR', 'Viés de status quo: a fricção da mudança é percebida como maior do que o benefício real de R$ 350 anuais', 'sesgo'),
  ('sesgo.status-quo.question.2.option.1.text', 'pt-BR', 'Faço a mudança — R$ 350 anuais são suficientes para dedicar 2 horas ao processo', 'sesgo'),
  ('sesgo.status-quo.question.2.option.1.reveal', 'pt-BR', 'Racional: o custo da mudança (tempo) é comparado explicitamente com o benefício (economia real)', 'sesgo'),
  ('sesgo.status-quo.fixation.0.question', 'pt-BR', 'Qual é o mecanismo principal por trás do viés de status quo?', 'sesgo'),
  ('sesgo.status-quo.fixation.0.option.0', 'pt-BR', 'A aversão à perda faz com que qualquer mudança pareça mais custosa do que os benefícios potenciais', 'sesgo'),
  ('sesgo.status-quo.fixation.0.option.1', 'pt-BR', 'A falta de informação sobre alternativas faz com que manter o atual pareça mais seguro', 'sesgo'),
  ('sesgo.status-quo.fixation.0.option.2', 'pt-BR', 'O medo de errar faz com que as pessoas evitem qualquer decisão ativa', 'sesgo'),
  ('sesgo.status-quo.fixation.1.question', 'pt-BR', 'Um experimento mudou o plano de previdência de opt-in para opt-out. O que aconteceu com a participação?', 'sesgo'),
  ('sesgo.status-quo.fixation.1.option.0', 'pt-BR', 'Subiu drasticamente — o padrão determina o comportamento mais do que a preferência real', 'sesgo'),
  ('sesgo.status-quo.fixation.1.option.1', 'pt-BR', 'Caiu — as pessoas rejeitaram a inscrição automática por questão de autonomia', 'sesgo'),
  ('sesgo.status-quo.fixation.1.option.2', 'pt-BR', 'Não mudou significativamente — as pessoas tomaram a mesma decisão independentemente do padrão', 'sesgo'),
  ('sesgo.status-quo.fixation.2.question', 'pt-BR', 'Qual é a diferença entre prudência e viés de status quo?', 'sesgo'),
  ('sesgo.status-quo.fixation.2.option.0', 'pt-BR', 'A prudência se baseia em análise deliberada; o status quo se baseia em inércia e desconforto com a mudança', 'sesgo'),
  ('sesgo.status-quo.fixation.2.option.1', 'pt-BR', 'A prudência é um viés emocional; o status quo é uma estratégia racional de baixo risco', 'sesgo'),
  ('sesgo.status-quo.fixation.2.option.2', 'pt-BR', 'Não há diferença real: ambos levam a manter a situação atual', 'sesgo'),
  ('sesgo.autocontrol.name', 'pt-BR', 'Viés de Autocontrole', 'sesgo'),
  ('sesgo.autocontrol.definition', 'pt-BR', 'Não agimos em prol dos nossos objetivos de longo prazo por falta de autodisciplina e preferência pela gratificação imediata.', 'sesgo'),
  ('sesgo.autocontrol.description', 'pt-BR', 'O Viés de Autocontrole (CFA) e o Desconto Hiperbólico (Thaler) descrevem o mesmo fenômeno: somos incapazes de executar hoje o que em teoria queremos para o futuro. Não é um problema de conhecimento — sabemos que devemos poupar. É um problema de força de vontade sob pressão.', 'sesgo'),
  ('sesgo.autocontrol.mechanism', 'pt-BR', 'Dan Ariely distingue o "eu em estado frio" (racional, planejador) do "eu em estado quente" (impulsivo, sob pressão). Em estado frio, fazemos escolhas virtuosas. Em estado quente, o Sistema 1 assume o controle. A "lacuna de empatia" nos impede de prever o quanto nosso eu quente vai diferir do eu frio.', 'sesgo'),
  ('sesgo.autocontrol.trapQuestion', 'pt-BR', 'Quanto você planeja poupar no próximo mês? Agora: quanto você poupou este mês? A diferença entre esses dois números é sua "lacuna de autocontrole".', 'sesgo'),
  ('sesgo.autocontrol.example.0.label', 'pt-BR', 'Poupança', 'sesgo'),
  ('sesgo.autocontrol.example.0.text', 'pt-BR', 'Você sabe que deve poupar 20% do seu salário. Todo mês "este mês é a exceção" por algum motivo. Nunca poupamos tanto quanto planejamos a frio.', 'sesgo'),
  ('sesgo.autocontrol.example.1.label', 'pt-BR', 'Investimento', 'sesgo'),
  ('sesgo.autocontrol.example.1.text', 'pt-BR', 'Você planeja não verificar seu portfólio mais de uma vez por mês. Mas quando o mercado cai, você abre o app a cada hora e acaba vendendo no pior momento.', 'sesgo'),
  ('sesgo.autocontrol.example.2.label', 'pt-BR', 'Gasto', 'sesgo'),
  ('sesgo.autocontrol.example.2.text', 'pt-BR', 'Você decide não gastar com roupas este mês. Mas no shopping, vê uma oferta "única" e o eu quente vence.', 'sesgo'),
  ('sesgo.autocontrol.antidote.0', 'pt-BR', 'Automatize a poupança: transfira automaticamente antes que o dinheiro chegue à sua conta corrente.', 'sesgo'),
  ('sesgo.autocontrol.antidote.1', 'pt-BR', 'Use a ferramenta de Thaler: "Save More Tomorrow" — comprometa hoje um % dos seus futuros aumentos de salário.', 'sesgo'),
  ('sesgo.autocontrol.antidote.2', 'pt-BR', 'Elimine a tentação do ambiente: delete apps de trading se você verifica em excesso; esconda cartões de crédito.', 'sesgo'),
  ('sesgo.autocontrol.antidote.3', 'pt-BR', 'Contratos de compromisso (commitment devices): penalidades reais se você não cumprir suas metas.', 'sesgo'),
  ('sesgo.autocontrol.question.0.situation', 'pt-BR', 'Você recebe um bônus de R$ 3.000. Tem uma dívida de cartão a 20% de juros. O que você faz?', 'sesgo'),
  ('sesgo.autocontrol.question.0.option.0.text', 'pt-BR', 'Pago a dívida imediatamente — é a decisão matematicamente ótima', 'sesgo'),
  ('sesgo.autocontrol.question.0.option.0.reveal', 'pt-BR', 'Racional: eliminar uma dívida a 20% é um retorno garantido de 20%, difícil de superar', 'sesgo'),
  ('sesgo.autocontrol.question.0.option.1.text', 'pt-BR', 'Gasto metade em algo que queria e pago metade da dívida', 'sesgo'),
  ('sesgo.autocontrol.question.0.option.1.reveal', 'pt-BR', 'Viés de autocontrole: o eu quente interfere na decisão ótima do eu frio', 'sesgo'),
  ('sesgo.autocontrol.question.1.situation', 'pt-BR', 'Você está há 4 horas em uma reunião exaustiva. Passam salgadinhos. O que você escolhe?', 'sesgo'),
  ('sesgo.autocontrol.question.1.option.0.text', 'pt-BR', 'O chocolate/biscoito — estou esgotado e preciso disso', 'sesgo'),
  ('sesgo.autocontrol.question.1.option.0.reveal', 'pt-BR', 'Viés de autocontrole + Ego Depletion: o Sistema 2 está esgotado e o Sistema 1 assume o controle', 'sesgo'),
  ('sesgo.autocontrol.question.1.option.1.text', 'pt-BR', 'Frutas secas — embora seja difícil, sigo meu plano alimentar', 'sesgo'),
  ('sesgo.autocontrol.question.1.option.1.reveal', 'pt-BR', 'Autocontrole ativo: o Sistema 2 exerce disciplina mesmo sob fadiga', 'sesgo'),
  ('sesgo.autocontrol.question.2.situation', 'pt-BR', 'O mercado caiu 8% hoje. Seu portfólio baixou R$ 4.000. O que você faz?', 'sesgo'),
  ('sesgo.autocontrol.question.2.option.0.text', 'pt-BR', 'Fico verificando o app a cada hora e eventualmente vendo para "estancar as perdas"', 'sesgo'),
  ('sesgo.autocontrol.question.2.option.0.reveal', 'pt-BR', 'Viés de autocontrole: o desconforto do eu quente destrói o plano do eu frio', 'sesgo'),
  ('sesgo.autocontrol.question.2.option.1.text', 'pt-BR', 'Lembro do meu plano de longo prazo e não faço nada até a revisão programada', 'sesgo'),
  ('sesgo.autocontrol.question.2.option.1.reveal', 'pt-BR', 'Racional: a aversão míope à perda destrói retornos — o plano existe exatamente para momentos como esse', 'sesgo'),
  ('sesgo.autocontrol.fixation.0.question', 'pt-BR', 'O que é o desconto hiperbólico?', 'sesgo'),
  ('sesgo.autocontrol.fixation.0.option.0', 'pt-BR', 'A tendência de preferir recompensas pequenas e imediatas a recompensas maiores no futuro', 'sesgo'),
  ('sesgo.autocontrol.fixation.0.option.1', 'pt-BR', 'Descontos que parecem atrativos mas têm custos ocultos no longo prazo', 'sesgo'),
  ('sesgo.autocontrol.fixation.0.option.2', 'pt-BR', 'A incapacidade de calcular corretamente o valor do dinheiro no tempo', 'sesgo'),
  ('sesgo.autocontrol.fixation.1.question', 'pt-BR', 'Você sabe que deveria poupar R$ 600 por mês, mas todo mês adia. O que explica esse padrão?', 'sesgo'),
  ('sesgo.autocontrol.fixation.1.option.0', 'pt-BR', 'Viés do presente: o eu futuro parece distante e abstrato; o prazer de gastar hoje parece concreto e imediato', 'sesgo'),
  ('sesgo.autocontrol.fixation.1.option.1', 'pt-BR', 'Viés de status quo: você prefere manter seus hábitos de gasto atuais', 'sesgo'),
  ('sesgo.autocontrol.fixation.1.option.2', 'pt-BR', 'Aversão à perda: você sente que poupar é perder dinheiro disponível', 'sesgo'),
  ('sesgo.autocontrol.fixation.2.question', 'pt-BR', 'Por que os pré-compromissos (precommitment) são eficazes contra esse viés?', 'sesgo'),
  ('sesgo.autocontrol.fixation.2.option.0', 'pt-BR', 'Porque eliminam a decisão no momento da tentação, quando o Sistema 1 domina', 'sesgo'),
  ('sesgo.autocontrol.fixation.2.option.1', 'pt-BR', 'Porque aumentam a culpa quando não cumprimos, o que nos motiva mais', 'sesgo'),
  ('sesgo.autocontrol.fixation.2.option.2', 'pt-BR', 'Porque tornam a poupança mais visível e fácil de monitorar', 'sesgo'),
  ('sesgo.endowment-effect.name', 'pt-BR', 'Efeito de Dotação', 'sesgo'),
  ('sesgo.endowment-effect.definition', 'pt-BR', 'Valorizamos mais um ativo simplesmente porque o possuímos.', 'sesgo'),
  ('sesgo.endowment-effect.description', 'pt-BR', 'Descrito por Kahneman e Thaler, o Efeito de Dotação viola a teoria econômica clássica: o preço pelo qual você estaria disposto a vender algo (WTA) deveria ser igual ao que pagaria para comprá-lo (WTP). Na prática, WTA sempre supera WTP — somos donos sentimentais dos nossos ativos.', 'sesgo'),
  ('sesgo.endowment-effect.mechanism', 'pt-BR', 'Uma vez que possuímos algo, abrir mão dele parece uma perda. A aversão à perda entra em cena: a dor de perder a posse supera o prazer de ganhar o dinheiro. Dan Ariely observou que começamos a gostar das coisas quase imediatamente após possuí-las, ou até mesmo ao imaginar que as possuímos.', 'sesgo'),
  ('sesgo.endowment-effect.trapQuestion', 'pt-BR', 'Você ganhou em um sorteio um ingresso VIP de R$ 450 para o evento dos seus sonhos. Alguém te oferece R$ 450 em dinheiro por ele. Você vende? — A maioria diz não. Mas antes de ganhá-lo, você não teria pago R$ 450 por ele.', 'sesgo'),
  ('sesgo.endowment-effect.example.0.label', 'pt-BR', 'Investimento', 'sesgo')
INSERT INTO public.translations (key, lang, text, domain) VALUES
  ('sesgo.endowment-effect.example.0.text', 'pt-BR', 'Um investidor recebe ações de sua empresa como remuneração. Embora racionalmente saiba que está superexposto a um único ativo, não as vende porque "são minhas, eu as ganhei".', 'sesgo'),
  ('sesgo.endowment-effect.example.1.label', 'pt-BR', 'Imóveis', 'sesgo'),
  ('sesgo.endowment-effect.example.1.text', 'pt-BR', 'Vendedores de imóveis sempre acreditam que sua propriedade vale mais do que o mercado indica. O apego emocional infla a avaliação.', 'sesgo'),
  ('sesgo.endowment-effect.example.2.label', 'pt-BR', 'Negociação', 'sesgo'),
  ('sesgo.endowment-effect.example.2.text', 'pt-BR', 'Em negociações, quem já "tem" algo (um contrato, um direito) exige mais para ceder do que a contraparte pagaria para adquiri-lo, bloqueando acordos eficientes.', 'sesgo'),
  ('sesgo.endowment-effect.antidote.0', 'pt-BR', 'Teste do dinheiro novo: "Se eu tivesse esse ativo em dinheiro hoje, eu compraria essa posição a esse preço?"', 'sesgo'),
  ('sesgo.endowment-effect.antidote.1', 'pt-BR', 'Avaliação externa: peça a alguém sem vínculo emocional que avalie o ativo.', 'sesgo'),
  ('sesgo.endowment-effect.antidote.2', 'pt-BR', 'Separar a história do ativo do seu valor de mercado atual.', 'sesgo'),
  ('sesgo.endowment-effect.antidote.3', 'pt-BR', 'Revisão periódica forçada: "O quanto estou avaliando isso de forma objetiva, ou apenas porque o possuo?"', 'sesgo'),
  ('sesgo.endowment-effect.question.0.situation', 'pt-BR', 'Você tem ações da sua empresa que recebeu como bônus. Elas representam 40% do seu portfólio. O que você faz?', 'sesgo'),
  ('sesgo.endowment-effect.question.0.option.0.text', 'pt-BR', 'Mantenho — são "minhas" ações, eu as ganhei, confio na empresa', 'sesgo'),
  ('sesgo.endowment-effect.question.0.option.0.reveal', 'pt-BR', 'Efeito de dotação: a posse e a origem criam apego que nubla a avaliação de concentração de risco', 'sesgo'),
  ('sesgo.endowment-effect.question.0.option.1.text', 'pt-BR', 'Avalio se ter 40% em uma única ação é prudente, independentemente de sua origem', 'sesgo'),
  ('sesgo.endowment-effect.question.0.option.1.reveal', 'pt-BR', 'Racional: as ações devem ser avaliadas como qualquer outro investimento, sem privilégio por sua história', 'sesgo'),
  ('sesgo.endowment-effect.question.1.situation', 'pt-BR', 'Você comprou um carro há 3 anos. Quer vendê-lo. O mercado o avalia em R$ 50.000. A que preço você o coloca à venda?', 'sesgo'),
  ('sesgo.endowment-effect.question.1.option.0.text', 'pt-BR', 'R$ 65.000 ou mais — meu carro está em perfeito estado e vale mais do que a média', 'sesgo'),
  ('sesgo.endowment-effect.question.1.option.0.reveal', 'pt-BR', 'Efeito de dotação: todos os donos acreditam que seu carro é "especial" e está em melhor estado do que a média', 'sesgo'),
  ('sesgo.endowment-effect.question.1.option.1.text', 'pt-BR', 'R$ 50.000 ou o preço de mercado — é o que um comprador racional pagaria', 'sesgo'),
  ('sesgo.endowment-effect.question.1.option.1.reveal', 'pt-BR', 'Racional: o mercado já incorpora o "perfeito estado" em sua avaliação média', 'sesgo'),
  ('sesgo.endowment-effect.question.2.situation', 'pt-BR', 'Você ganhou em um sorteio um ingresso para um show avaliado em R$ 600. Alguém te oferece R$ 600 em dinheiro por ele. Você vende?', 'sesgo'),
  ('sesgo.endowment-effect.question.2.option.0.text', 'pt-BR', 'Não — já é minha e a experiência vale mais do que o dinheiro', 'sesgo'),
  ('sesgo.endowment-effect.question.2.option.0.reveal', 'pt-BR', 'Efeito de dotação: se antes de ganhá-la você não teria pago R$ 600, por que agora ela vale mais?', 'sesgo'),
  ('sesgo.endowment-effect.question.2.option.1.text', 'pt-BR', 'Sim — se o ingresso vale exatamente o que me oferecem, a decisão é neutra', 'sesgo'),
  ('sesgo.endowment-effect.question.2.option.1.reveal', 'pt-BR', 'Racional: a posse não deveria criar valor adicional se o preço oferecido é de mercado', 'sesgo'),
  ('sesgo.endowment-effect.fixation.0.question', 'pt-BR', 'O que o experimento das canecas de café de Kahneman revela sobre o efeito dotação?', 'sesgo'),
  ('sesgo.endowment-effect.fixation.0.option.0', 'pt-BR', 'As pessoas pedem mais para vender algo do que pagariam para comprá-lo, só porque já o possuem', 'sesgo'),
  ('sesgo.endowment-effect.fixation.0.option.1', 'pt-BR', 'As pessoas valorizam mais objetos de uso cotidiano do que os de investimento', 'sesgo'),
  ('sesgo.endowment-effect.fixation.0.option.2', 'pt-BR', 'O preço de mercado não reflete o valor real que os consumidores atribuem aos produtos', 'sesgo'),
  ('sesgo.endowment-effect.fixation.1.question', 'pt-BR', 'Um investidor se recusa a vender ações herdadas de seu avô mesmo com desempenho ruim. Como o efeito dotação opera aqui?', 'sesgo'),
  ('sesgo.endowment-effect.fixation.1.option.0', 'pt-BR', 'A posse e o vínculo emocional inflam o valor percebido além do valor financeiro real', 'sesgo'),
  ('sesgo.endowment-effect.fixation.1.option.1', 'pt-BR', 'O viés de status quo o impede de tomar decisões ativas sobre o portfólio', 'sesgo'),
  ('sesgo.endowment-effect.fixation.1.option.2', 'pt-BR', 'A aversão à perda o faz temer cristalizar a perda ao vender', 'sesgo'),
  ('sesgo.endowment-effect.fixation.2.question', 'pt-BR', 'Qual é a pergunta-chave para neutralizar o efeito dotação em decisões financeiras?', 'sesgo'),
  ('sesgo.endowment-effect.fixation.2.option.0', 'pt-BR', '"Se eu não tivesse esse ativo hoje, eu o compraria a esse preço?" — se a resposta for não, vale repensar mantê-lo', 'sesgo'),
  ('sesgo.endowment-effect.fixation.2.option.1', 'pt-BR', '"Há quanto tempo tenho esse ativo?" — mais tempo justifica mais apego', 'sesgo'),
  ('sesgo.endowment-effect.fixation.2.option.2', 'pt-BR', '"O que outros investidores fariam com esse ativo?" — a comparação social neutraliza o viés', 'sesgo'),
  ('sesgo.halo-effect.name', 'pt-BR', 'Efeito Halo', 'sesgo'),
  ('sesgo.halo-effect.definition', 'pt-BR', 'Generalizamos um atributo positivo (ou negativo) de uma pessoa ou empresa para todas as suas demais características.', 'sesgo'),
  ('sesgo.halo-effect.description', 'pt-BR', 'O Efeito Halo é uma obra-prima do Sistema 1: diante da ausência de informação completa, usamos a emoção que um traço visível nos desperta para "preencher" os espaços em branco. Se uma empresa faz um produto que adoramos, assumimos que suas finanças, gestão e perspectivas também são brilhantes.', 'sesgo'),
  ('sesgo.halo-effect.mechanism', 'pt-BR', 'Kahneman explica que o Sistema 1 detesta a ambiguidade e busca narrativas simples e coerentes. Diante da pergunta difícil "Esta empresa é um bom investimento?", ele a substitui por "Eu gosto do produto?". A resposta emocional preenche os vazios cognitivos.', 'sesgo'),
  ('sesgo.halo-effect.trapQuestion', 'pt-BR', 'Seu celular favorito é da marca X. É rápido e lindo. A empresa abre o capital. Você tem liquidez. O que você faz? — Comprar porque o produto é incrível é o Efeito Halo: produto ≠ ação.', 'sesgo'),
  ('sesgo.halo-effect.example.0.label', 'pt-BR', 'Investimento', 'sesgo'),
  ('sesgo.halo-effect.example.0.text', 'pt-BR', 'A Apple faz produtos que você ama. Suas ações sempre valem mais do que os fundamentals justificam porque o halo do produto contamina a avaliação. "Bom produto = boa ação" é o Efeito Halo aplicado.', 'sesgo'),
  ('sesgo.halo-effect.example.1.label', 'pt-BR', 'Contratação', 'sesgo'),
  ('sesgo.halo-effect.example.1.text', 'pt-BR', 'Um candidato atraente e bem vestido parece mais competente na entrevista, independentemente de suas respostas técnicas. A aparência irradia halo sobre a inteligência.', 'sesgo'),
  ('sesgo.halo-effect.example.2.label', 'pt-BR', 'Empresa', 'sesgo'),
  ('sesgo.halo-effect.example.2.text', 'pt-BR', 'Um CEO carismático que fala bem em conferências parece mais capaz de executar a estratégia, mesmo que os números digam outra coisa.', 'sesgo'),
  ('sesgo.halo-effect.antidote.0', 'pt-BR', 'Separar explicitamente: "Eu gosto do produto?" vs. "A ação é um bom investimento?"', 'sesgo'),
  ('sesgo.halo-effect.antidote.1', 'pt-BR', 'Avalie a empresa como se nunca tivesse usado seu produto — como você enxerga os números?', 'sesgo'),
  ('sesgo.halo-effect.antidote.2', 'pt-BR', 'Busque ativamente os pontos fracos das empresas que mais admira.', 'sesgo'),
  ('sesgo.halo-effect.antidote.3', 'pt-BR', 'O teste do CEO antipático: você avaliaria essa empresa da mesma forma se o CEO fosse desagradável, mas os números fossem iguais?', 'sesgo'),
  ('sesgo.halo-effect.question.0.situation', 'pt-BR', 'Você é fã de uma marca de carros de luxo. Eles acabaram de abrir o capital. O que você faz?', 'sesgo'),
  ('sesgo.halo-effect.question.0.option.0.text', 'pt-BR', 'Compro — se o produto é tão bom, a empresa deve ser excelente', 'sesgo'),
  ('sesgo.halo-effect.question.0.option.0.reveal', 'pt-BR', 'Efeito Halo: a admiração pelo produto contamina a avaliação financeira da ação', 'sesgo'),
  ('sesgo.halo-effect.question.0.option.1.text', 'pt-BR', 'Analiso o índice dívida/capital, margens e perspectivas como se não conhecesse a marca', 'sesgo'),
  ('sesgo.halo-effect.question.0.option.1.reveal', 'pt-BR', 'Racional: separar a experiência como consumidor da análise como investidor', 'sesgo'),
  ('sesgo.halo-effect.question.1.situation', 'pt-BR', 'Um gestor de fundos é atraente, se expressa com perfeição e tem um MBA por Harvard. Que peso você dá ao histórico de retornos dele?', 'sesgo'),
  ('sesgo.halo-effect.question.1.option.0.text', 'pt-BR', 'O MBA e a presença me dão muita confiança — reviso o histórico de forma', 'sesgo'),
  ('sesgo.halo-effect.question.1.option.0.reveal', 'pt-BR', 'Efeito Halo: atributos superficiais (aparência, credenciais) contaminam a avaliação do que realmente importa (resultados)', 'sesgo'),
  ('sesgo.halo-effect.question.1.option.1.text', 'pt-BR', 'O histórico de retornos ajustados ao risco é o que determina minha decisão', 'sesgo'),
  ('sesgo.halo-effect.question.1.option.1.reveal', 'pt-BR', 'Racional: os retornos auditados são o único indicador que prediz desempenho futuro com alguma validade', 'sesgo'),
  ('sesgo.halo-effect.question.2.situation', 'pt-BR', 'Uma empresa cujo produto você usa e adora reporta prejuízos pelo terceiro trimestre consecutivo. Como você reage?', 'sesgo'),
  ('sesgo.halo-effect.question.2.option.0.text', 'pt-BR', 'Devem ser problemas temporários — é uma empresa boa demais para fracassar', 'sesgo'),
  ('sesgo.halo-effect.question.2.option.0.reveal', 'pt-BR', 'Efeito Halo inverso: o amor pela marca cria resistência a atualizar a visão diante de evidências negativas', 'sesgo'),
  ('sesgo.halo-effect.question.2.option.1.text', 'pt-BR', 'Analiso se há razões fundamentais para as perdas e atualizo minha tese', 'sesgo'),
  ('sesgo.halo-effect.question.2.option.1.reveal', 'pt-BR', 'Racional: os dados atuais pesam mais do que a história emocional com a empresa', 'sesgo'),
  ('sesgo.halo-effect.fixation.0.question', 'pt-BR', 'O que é o efeito halo no contexto de investimentos?', 'sesgo'),
  ('sesgo.halo-effect.fixation.0.option.0', 'pt-BR', 'Generalizar atributos positivos de uma empresa para todos os seus demais aspectos, formando uma imagem distorcida', 'sesgo'),
  ('sesgo.halo-effect.fixation.0.option.1', 'pt-BR', 'O brilho que um ativo gera em todo o portfólio quando sobe de valor', 'sesgo'),
  ('sesgo.halo-effect.fixation.0.option.2', 'pt-BR', 'A tendência de investir em empresas conhecidas porque a marca gera confiança', 'sesgo'),
  ('sesgo.halo-effect.fixation.1.question', 'pt-BR', 'Uma empresa de tecnologia muito admirada lança um produto em um mercado que não conhece. Os analistas a avaliam positivamente por inércia. Qual viés está operando?', 'sesgo'),
  ('sesgo.halo-effect.fixation.1.option.0', 'pt-BR', 'Efeito halo: o sucesso passado em tecnologia contamina a avaliação de uma aposta em um setor diferente', 'sesgo'),
  ('sesgo.halo-effect.fixation.1.option.1', 'pt-BR', 'Viés de disponibilidade: o sucesso recente da empresa é fácil de lembrar', 'sesgo'),
  ('sesgo.halo-effect.fixation.1.option.2', 'pt-BR', 'Representatividade: se parece com outras empresas que diversificaram com sucesso', 'sesgo'),
  ('sesgo.halo-effect.fixation.2.question', 'pt-BR', 'Qual é o antídoto mais direto contra o efeito halo ao avaliar um investimento?', 'sesgo'),
  ('sesgo.halo-effect.fixation.2.option.0', 'pt-BR', 'Analisar cada dimensão separadamente — produto, finanças, equipe — sem deixar que uma contamine as demais', 'sesgo'),
  ('sesgo.halo-effect.fixation.2.option.1', 'pt-BR', 'Buscar opiniões de pessoas que não conheçam a empresa para evitar o viés', 'sesgo'),
  ('sesgo.halo-effect.fixation.2.option.2', 'pt-BR', 'Comparar a empresa com sua concorrência direta antes de avaliá-la de forma isolada', 'sesgo'),
  ('sesgo.herding.name', 'pt-BR', 'Efeito Manada', 'sesgo'),
  ('sesgo.herding.definition', 'pt-BR', 'Tendemos a seguir as decisões da multidão, abandonando nossa própria análise.', 'sesgo'),
  ('sesgo.herding.description', 'pt-BR', 'O Efeito Manada (Social Proof) é a tendência de assumir que, se muitos estão fazendo algo, deve ser correto. Em investimentos, esse viés alimenta bolhas (todos compram) e crashes (todos vendem). Segundo o CFA, é um Erro Cognitivo: o investidor falha em processar informações de forma independente.', 'sesgo'),
  ('sesgo.herding.mechanism', 'pt-BR', 'O cérebro substitui uma pergunta difícil ("Quais são os fundamentals deste ativo?") por uma fácil ("Todos os outros estão comprando?"). Sob incerteza, o consenso atua como proxy da verdade. Robert Cialdini explica que esse mecanismo se amplifica com duas condições: incerteza e similaridade.', 'sesgo'),
  ('sesgo.herding.trapQuestion', 'pt-BR', 'Você faz parte de um comitê. Todos aprovam um projeto com números frágeis. Como você age? — Em um ambiente neutro, 90% diz que votaria contra. Na sala, a pressão do grupo muda o voto.', 'sesgo'),
  ('sesgo.herding.example.0.label', 'pt-BR', 'Bolha', 'sesgo'),
  ('sesgo.herding.example.0.text', 'pt-BR', 'Em 2021, milhões compraram NFTs porque "todo mundo estava fazendo isso". Ninguém queria perder o rali. O resultado foi uma queda de 97% em muitos ativos.', 'sesgo'),
  ('sesgo.herding.example.1.label', 'pt-BR', 'Institucional', 'sesgo'),
  ('sesgo.herding.example.1.text', 'pt-BR', 'Gestores profissionais também sofrem herding: é mais seguro errar junto com a maioria ("todos perdemos") do que errar sozinho ("por que você tomou essa posição?").', 'sesgo'),
  ('sesgo.herding.example.2.label', 'pt-BR', 'FOMO', 'sesgo'),
  ('sesgo.herding.example.2.text', 'pt-BR', 'Uma ação sobe 30% em uma semana. O volume de buscas no Google explode. Novos investidores entram justamente quando os mais informados estão saindo.', 'sesgo'),
  ('sesgo.herding.antidote.0', 'pt-BR', 'Antes de qualquer decisão, escreva sua análise ANTES de conhecer a posição dos outros.', 'sesgo'),
  ('sesgo.herding.antidote.1', 'pt-BR', 'O teste do contrarian: qual argumento faria o melhor investidor que vai na direção oposta?', 'sesgo'),
  ('sesgo.herding.antidote.2', 'pt-BR', 'O consenso é informação, não verdade. Pergunte: o que sabem os que estão comprando que eu não sei?', 'sesgo'),
  ('sesgo.herding.antidote.3', 'pt-BR', 'Fuja de decisões tomadas sob urgência e pressão social — é exatamente quando o herding ataca.', 'sesgo'),
  ('sesgo.herding.question.0.situation', 'pt-BR', 'Um ativo que você não conhece subiu 80% este mês. Todos os seus amigos já investiram. O que você faz?', 'sesgo'),
  ('sesgo.herding.question.0.option.0.text', 'pt-BR', 'Entro — se tanta gente está ganhando, sabem algo que eu não sei', 'sesgo'),
  ('sesgo.herding.question.0.option.0.reveal', 'pt-BR', 'Efeito Manada: o consenso atua como substituto da análise. Mas quem entrou primeiro já está saindo', 'sesgo'),
  ('sesgo.herding.question.0.option.1.text', 'pt-BR', 'Pesquiso os fundamentals antes de me mover, independentemente do que meus amigos estejam fazendo', 'sesgo'),
  ('sesgo.herding.question.0.option.1.reveal', 'pt-BR', 'Racional: quando todos falam de um investimento, geralmente já é tarde para entrar', 'sesgo'),
  ('sesgo.herding.question.1.situation', 'pt-BR', 'No comitê de investimentos, 4 dos 5 membros aprovam um projeto com projeções que parecem otimistas para você. Você é o último a votar. O que você faz?', 'sesgo'),
  ('sesgo.herding.question.1.option.0.text', 'pt-BR', 'Voto a favor — se quatro pessoas mais inteligentes do que eu aprovaram, elas enxergam algo', 'sesgo')
INSERT INTO public.translations (key, lang, text, domain) VALUES
  ('sesgo.herding.question.1.option.0.reveal', 'pt-BR', 'Herding institucional (Groupthink): os comitês destroem o valor da informação privada de cada membro', 'sesgo'),
  ('sesgo.herding.question.1.option.1.text', 'pt-BR', 'Voto contra e explico minhas dúvidas — o valor de estar no comitê é exatamente votar de forma independente', 'sesgo'),
  ('sesgo.herding.question.1.option.1.reveal', 'pt-BR', 'Racional: a diversidade de opiniões em um comitê é seu principal ativo. Ceder ao consenso a elimina', 'sesgo'),
  ('sesgo.herding.question.2.situation', 'pt-BR', 'O mercado caiu 15% em duas semanas. Todos estão vendendo. A mídia fala em "colapso histórico". O que você faz com seu portfólio de longo prazo?', 'sesgo'),
  ('sesgo.herding.question.2.option.0.text', 'pt-BR', 'Vendo também para evitar perdas maiores — se todos estão saindo, algo grave está acontecendo', 'sesgo'),
  ('sesgo.herding.question.2.option.0.reveal', 'pt-BR', 'Herding na baixa: as crises geram o pior momento para seguir a multidão — é quando os mais informados compram', 'sesgo'),
  ('sesgo.herding.question.2.option.1.text', 'pt-BR', 'Analiso se os fundamentals das minhas posições mudaram, não se o sentimento do mercado mudou', 'sesgo'),
  ('sesgo.herding.question.2.option.1.reveal', 'pt-BR', 'Racional: preço e valor divergem mais em pânico. O herding vende quando deveria comprar', 'sesgo'),
  ('sesgo.herding.fixation.0.question', 'pt-BR', 'Por que o efeito manada se intensifica em condições de incerteza?', 'sesgo'),
  ('sesgo.herding.fixation.0.option.0', 'pt-BR', 'Porque sob incerteza, o consenso atua como substituto da análise — se todo mundo está fazendo, deve ser certo', 'sesgo'),
  ('sesgo.herding.fixation.0.option.1', 'pt-BR', 'Porque em mercados voláteis a informação individual perde valor frente à coletiva', 'sesgo'),
  ('sesgo.herding.fixation.0.option.2', 'pt-BR', 'Porque a incerteza ativa o Sistema 2, que busca validação social antes de decidir', 'sesgo'),
  ('sesgo.herding.fixation.1.question', 'pt-BR', 'Gestores profissionais de fundos também sofrem efeito manada. Por quê?', 'sesgo'),
  ('sesgo.herding.fixation.1.option.0', 'pt-BR', 'Porque errar junto com todos é profissionalmente menos custoso do que errar sozinho com uma posição contrária', 'sesgo'),
  ('sesgo.herding.fixation.1.option.1', 'pt-BR', 'Porque têm acesso às mesmas informações e naturalmente chegam às mesmas conclusões', 'sesgo'),
  ('sesgo.herding.fixation.1.option.2', 'pt-BR', 'Porque os reguladores exigem que mantenham portfólios similares ao índice de referência', 'sesgo'),
  ('sesgo.herding.fixation.2.question', 'pt-BR', 'O que distingue o investidor que resiste ao efeito manada do que cede?', 'sesgo'),
  ('sesgo.herding.fixation.2.option.0', 'pt-BR', 'Escrever e documentar sua análise antes de conhecer a posição do mercado ou de outros investidores', 'sesgo'),
  ('sesgo.herding.fixation.2.option.1', 'pt-BR', 'Ter mais experiência em mercados e conhecer mais casos históricos de bolhas', 'sesgo'),
  ('sesgo.herding.fixation.2.option.2', 'pt-BR', 'Investir em ativos menos acompanhados pelo mercado, onde há menos pressão de grupo', 'sesgo'),
  ('sesgo.optimism-bias.name', 'pt-BR', 'Viés de Otimismo', 'sesgo'),
  ('sesgo.optimism-bias.definition', 'pt-BR', 'Acreditamos sistematicamente que temos menos probabilidade de vivenciar eventos negativos e mais de vivenciar positivos do que a média estatística.', 'sesgo'),
  ('sesgo.optimism-bias.description', 'pt-BR', 'O Viés de Otimismo é o "gêmeo" do Excesso de Confiança. Juntos explicam por que investidores assumem mais risco do que deveriam, empreendedores subestimam o fracasso e gestores prometem rendimentos impossíveis. Nosso ego precisa acreditar que o futuro será brilhante e que somos excepcionais.', 'sesgo'),
  ('sesgo.optimism-bias.mechanism', 'pt-BR', 'O Sistema 1 opera sob WYSIATI: ao planejar, foca no cenário ideal e ignora contingências. A Falácia do Planejamento (Kahneman) é sua manifestação mais clara: projetos que sempre são entregues com atraso e acima do orçamento porque o plano assumiu o melhor cenário.', 'sesgo'),
  ('sesgo.optimism-bias.trapQuestion', 'pt-BR', 'Você inicia um projeto importante. Você define o orçamento e o prazo incluindo uma margem de 30% para imprevistos, ou propõe o cenário mais otimista para "demonstrar rentabilidade"? — A frio, todos dizem que incluem margem. Na prática, quase ninguém faz isso.', 'sesgo'),
  ('sesgo.optimism-bias.example.0.label', 'pt-BR', 'Falácia do planejamento', 'sesgo'),
  ('sesgo.optimism-bias.example.0.text', 'pt-BR', '90% dos projetos de construção de infraestrutura chegam com atraso e acima do orçamento. O otimismo dos planejadores é sistemático, não acidental.', 'sesgo'),
  ('sesgo.optimism-bias.example.1.label', 'pt-BR', 'Empreendedorismo', 'sesgo'),
  ('sesgo.optimism-bias.example.1.text', 'pt-BR', '90% dos empreendedores acredita estar nos 10% que vão sobreviver. Estatisticamente, 90% das startups fracassam em 5 anos.', 'sesgo'),
  ('sesgo.optimism-bias.example.2.label', 'pt-BR', 'Investimento', 'sesgo'),
  ('sesgo.optimism-bias.example.2.text', 'pt-BR', 'Investidores individuais estimam retornos médios de 15–20% ao ano para seus portfólios, quando o mercado historicamente entrega 8–10%.', 'sesgo'),
  ('sesgo.optimism-bias.antidote.0', 'pt-BR', 'Outside View (Visão Externa): qual é a taxa base de sucesso para projetos semelhantes ao seu?', 'sesgo'),
  ('sesgo.optimism-bias.antidote.1', 'pt-BR', 'Pré-mortem: imagine que seu plano falhou — quais foram as 3 principais razões?', 'sesgo'),
  ('sesgo.optimism-bias.antidote.2', 'pt-BR', 'Planeje tendo o cenário pessimista como base, não o otimista.', 'sesgo'),
  ('sesgo.optimism-bias.antidote.3', 'pt-BR', 'Compartilhe seus planos com alguém que não tenha interesse emocional para identificar os pontos cegos.', 'sesgo'),
  ('sesgo.optimism-bias.question.0.situation', 'pt-BR', 'Você está lançando um negócio. Como você define o orçamento e o cronograma inicial?', 'sesgo'),
  ('sesgo.optimism-bias.question.0.option.0.text', 'pt-BR', 'Proponho o cenário mais rápido e barato — é preciso mostrar rentabilidade atraente', 'sesgo'),
  ('sesgo.optimism-bias.question.0.option.0.reveal', 'pt-BR', 'Viés de Otimismo / Falácia do Planejamento: 90% dos projetos chegam com atraso e acima do orçamento exatamente por essa razão', 'sesgo'),
  ('sesgo.optimism-bias.question.0.option.1.text', 'pt-BR', 'Adiciono 30–40% de tempo e capital extra sobre minha estimativa base', 'sesgo'),
  ('sesgo.optimism-bias.question.0.option.1.reveal', 'pt-BR', 'Racional: a "Visão Externa" mostra que projetos sempre custam mais e demoram mais do que o planejado', 'sesgo'),
  ('sesgo.optimism-bias.question.1.situation', 'pt-BR', 'Qual você acha que é a probabilidade de que seu próximo investimento gere retornos acima do mercado?', 'sesgo'),
  ('sesgo.optimism-bias.question.1.option.0.text', 'pt-BR', 'Alta (70%+) — tenho informações e análises que o mercado ainda não incorporou', 'sesgo'),
  ('sesgo.optimism-bias.question.1.option.0.reveal', 'pt-BR', 'Viés de Otimismo: os mercados são competitivos. A maioria dos investidores ativos não supera o índice de forma consistente', 'sesgo'),
  ('sesgo.optimism-bias.question.1.option.1.text', 'pt-BR', 'Modesta (50% ou menos) — os mercados são eficientes e a superioridade consistente é rara', 'sesgo'),
  ('sesgo.optimism-bias.question.1.option.1.reveal', 'pt-BR', 'Racional: a humildade estatística é o ponto de partida correto. Superar o mercado é possível, mas difícil', 'sesgo'),
  ('sesgo.optimism-bias.question.2.situation', 'pt-BR', 'Sua startup tem 18 meses de capital. Você está planejando a próxima captação. Com quanto tempo de antecedência começa?', 'sesgo'),
  ('sesgo.optimism-bias.question.2.option.0.text', 'pt-BR', '3 a 4 meses antes — com as minhas métricas, não deveria demorar tanto para fechar', 'sesgo'),
  ('sesgo.optimism-bias.question.2.option.0.reveal', 'pt-BR', 'Viés de otimismo: captações levam em média 6 a 9 meses. A maioria dos founders começa tarde exatamente por essa razão', 'sesgo'),
  ('sesgo.optimism-bias.question.2.option.1.text', 'pt-BR', '9 a 12 meses antes — o processo sempre demora mais do que o esperado', 'sesgo'),
  ('sesgo.optimism-bias.question.2.option.1.reveal', 'pt-BR', 'Racional: planejar a partir do cenário pessimista dá margem para o mundo real', 'sesgo'),
  ('sesgo.optimism-bias.fixation.0.question', 'pt-BR', 'O que é a Falácia do Planejamento e quem a descreveu?', 'sesgo'),
  ('sesgo.optimism-bias.fixation.0.option.0', 'pt-BR', 'A tendência sistemática de subestimar o tempo, o custo e os riscos de projetos futuros, descrita por Kahneman', 'sesgo'),
  ('sesgo.optimism-bias.fixation.0.option.1', 'pt-BR', 'O erro de planejar com cenários pessimistas que nunca se materializam, descrito por Thaler', 'sesgo'),
  ('sesgo.optimism-bias.fixation.0.option.2', 'pt-BR', 'A dificuldade de fazer planos de longo prazo quando o futuro é muito incerto, descrita por Ariely', 'sesgo'),
  ('sesgo.optimism-bias.fixation.1.question', 'pt-BR', '90% dos motoristas acredita dirigir melhor do que a média. O que isso ilustra?', 'sesgo'),
  ('sesgo.optimism-bias.fixation.1.option.0', 'pt-BR', 'Que sistematicamente nos colocamos acima da média em habilidades, o que é estatisticamente impossível para a maioria', 'sesgo'),
  ('sesgo.optimism-bias.fixation.1.option.1', 'pt-BR', 'Que as pessoas mentem sobre suas habilidades para parecer melhores diante dos outros', 'sesgo'),
  ('sesgo.optimism-bias.fixation.1.option.2', 'pt-BR', 'Que o otimismo é uma estratégia racional para manter a motivação', 'sesgo'),
  ('sesgo.optimism-bias.fixation.2.question', 'pt-BR', 'O que é o "outside view" (visão externa) e por que combate o viés de otimismo?', 'sesgo'),
  ('sesgo.optimism-bias.fixation.2.option.0', 'pt-BR', 'Perguntar qual é a taxa base de sucesso para projetos semelhantes ao seu, em vez de se concentrar apenas no seu caso particular', 'sesgo'),
  ('sesgo.optimism-bias.fixation.2.option.1', 'pt-BR', 'Pedir a opinião de pessoas externas à sua equipe antes de tomar uma decisão importante', 'sesgo'),
  ('sesgo.optimism-bias.fixation.2.option.2', 'pt-BR', 'Analisar dados históricos do mercado em vez de projeções futuras', 'sesgo'),
  ('sesgo.authority-bias.name', 'pt-BR', 'Viés de Autoridade', 'sesgo'),
  ('sesgo.authority-bias.definition', 'pt-BR', 'Damos peso excessivo à opinião de figuras que percebemos como especialistas, sem questionar se realmente o são.', 'sesgo'),
  ('sesgo.authority-bias.description', 'pt-BR', 'O Viés de Autoridade (Cialdini) é um dos seus seis Princípios de Influência: somos programados para obedecer a figuras de autoridade como atalho cognitivo. Em finanças, isso nos faz abandonar nossa própria análise diante de qualquer figura com credenciais, título ou aparente confiança.', 'sesgo'),
  ('sesgo.authority-bias.mechanism', 'pt-BR', 'O cérebro é biologicamente projetado para usar a autoridade como sinal de confiabilidade — evolutivamente, isso economizou energia e tempo. O Sistema 1 converte credenciais (título, roupa, confiança) em permissão para não pensar. O problema: credenciais nem sempre predizem competência, e especialistas têm conflitos de interesse.', 'sesgo'),
  ('sesgo.authority-bias.trapQuestion', 'pt-BR', 'Um célebre Nobel de Economia publica um modelo de investimento inovador. O que você faz? A) Revisar o modelo com cautela buscando vulnerabilidades. B) Adotá-lo — o nível dele garante resultados. — O LTCM tinha dois Nobel na equipe e quebrou espetacularmente.', 'sesgo'),
  ('sesgo.authority-bias.example.0.label', 'pt-BR', 'Finanças', 'sesgo'),
  ('sesgo.authority-bias.example.0.text', 'pt-BR', 'Madoff conduziu a maior fraude financeira da história (US$ 65 bilhões) durante décadas. Os investidores nunca auditaram suas estratégias porque sua autoridade como ex-presidente do NASDAQ era sinal suficiente.', 'sesgo'),
  ('sesgo.authority-bias.example.1.label', 'pt-BR', 'Investimento', 'sesgo'),
  ('sesgo.authority-bias.example.1.text', 'pt-BR', 'Um Nobel de Economia publica um modelo. Os fundos o adotam sem questionar seus pressupostos. O LTCM quebrou com dois Nobel na equipe.', 'sesgo'),
  ('sesgo.authority-bias.example.2.label', 'pt-BR', 'Redes sociais', 'sesgo'),
  ('sesgo.authority-bias.example.2.text', 'pt-BR', 'Influencers financeiros com milhões de seguidores movem mercados. O público assume que quem tem muitos seguidores sabe mais.', 'sesgo'),
  ('sesgo.authority-bias.antidote.0', 'pt-BR', 'Separe as credenciais do argumento: o argumento se sustenta por si só, independente de quem o diz?', 'sesgo'),
  ('sesgo.authority-bias.antidote.1', 'pt-BR', 'Pergunte sempre: quais incentivos essa pessoa tem para me dar esse conselho?', 'sesgo'),
  ('sesgo.authority-bias.antidote.2', 'pt-BR', 'Busque a opinião de especialistas do lado oposto — se você só ouve um lado, está sob o viés.', 'sesgo'),
  ('sesgo.authority-bias.antidote.3', 'pt-BR', 'O teste do histórico auditado: qual é o track record real dessa pessoa em situações similares?', 'sesgo'),
  ('sesgo.authority-bias.question.0.situation', 'pt-BR', 'Um famoso gestor de fundos com 30 anos de experiência recomenda uma ação na televisão. O que você faz?', 'sesgo'),
  ('sesgo.authority-bias.question.0.option.0.text', 'pt-BR', 'Se ele diz com tanta convicção, deve saber algo — compro', 'sesgo'),
  ('sesgo.authority-bias.question.0.option.0.reveal', 'pt-BR', 'Viés de autoridade: especialistas também erram. Ele tem posição nessa ação? Qual é seu track record recente?', 'sesgo'),
  ('sesgo.authority-bias.question.0.option.1.text', 'pt-BR', 'Uso a tese dele como ponto de partida para minha própria análise, não como conclusão', 'sesgo'),
  ('sesgo.authority-bias.question.0.option.1.reveal', 'pt-BR', 'Racional: a autoridade pode apontar ideias interessantes, mas não substitui a análise própria', 'sesgo'),
  ('sesgo.authority-bias.question.1.situation', 'pt-BR', 'Seu assessor bancário — gravata, escritório luxuoso, MBA — recomenda um fundo de investimento com taxas de 2,5% ao ano. O que você faz?', 'sesgo'),
  ('sesgo.authority-bias.question.1.option.0.text', 'pt-BR', 'Se o banco recomenda, deve ser bom — contrato', 'sesgo'),
  ('sesgo.authority-bias.question.1.option.0.reveal', 'pt-BR', 'Viés de autoridade: assessores bancários têm incentivos para recomendar produtos do banco. 2,5% é muito alto', 'sesgo'),
  ('sesgo.authority-bias.question.1.option.1.text', 'pt-BR', 'Pergunto qual comissão ele recebe por indicar, comparo com ETFs e decido com informação', 'sesgo'),
  ('sesgo.authority-bias.question.1.option.1.reveal', 'pt-BR', 'Racional: em finanças, os incentivos do assessor frequentemente divergem do seu interesse', 'sesgo'),
  ('sesgo.authority-bias.question.2.situation', 'pt-BR', 'Um influencer com 3M de seguidores, que parece muito bem-sucedido, recomenda "a criptomoeda do momento". O que você faz?', 'sesgo'),
  ('sesgo.authority-bias.question.2.option.0.text', 'pt-BR', 'Se 3M de pessoas o seguem, algo ele sabe — pelo menos coloco um pouco', 'sesgo'),
  ('sesgo.authority-bias.question.2.option.0.reveal', 'pt-BR', 'Viés de autoridade + efeito manada: seguidores são prova social, não de competência. Muitos influencers foram pagos para promover', 'sesgo'),
  ('sesgo.authority-bias.question.2.option.1.text', 'pt-BR', 'Pesquiso se ele tem posição nesse ativo, qual é seu histórico real e os fundamentos do projeto', 'sesgo'),
  ('sesgo.authority-bias.question.2.option.1.reveal', 'pt-BR', 'Racional: incentivos e histórico são o que importa, não os seguidores nem a aparência de sucesso', 'sesgo'),
  ('sesgo.authority-bias.fixation.0.question', 'pt-BR', 'O que é a negligência da taxa base no viés de representatividade?', 'sesgo'),
  ('sesgo.authority-bias.fixation.0.option.0', 'pt-BR', 'Ignorar a probabilidade estatística real de que algo ocorra porque um caso concreto parece muito representativo', 'sesgo'),
  ('sesgo.authority-bias.fixation.0.option.1', 'pt-BR', 'Não considerar as taxas base ao calcular o retorno de um investimento', 'sesgo'),
  ('sesgo.authority-bias.fixation.0.option.2', 'pt-BR', 'Subestimar a importância das taxas de juros em decisões financeiras', 'sesgo'),
  ('sesgo.authority-bias.fixation.1.question', 'pt-BR', 'Uma startup tem um fundador jovem de moletom e escritório no Vale do Silício. Você a descreve como "a próxima Apple". Qual viés está operando?', 'sesgo'),
  ('sesgo.authority-bias.fixation.1.option.0', 'pt-BR', 'Representatividade: a semelhança superficial com o estereótipo de empresa bem-sucedida substitui a análise real', 'sesgo'),
  ('sesgo.authority-bias.fixation.1.option.1', 'pt-BR', 'Efeito halo: os atributos positivos do fundador se transferem para a empresa', 'sesgo'),
  ('sesgo.authority-bias.fixation.1.option.2', 'pt-BR', 'Viés de disponibilidade: você se lembra facilmente de casos de startups bem-sucedidas semelhantes', 'sesgo')
INSERT INTO public.translations (key, lang, text, domain) VALUES
  ('sesgo.authority-bias.fixation.2.question', 'pt-BR', 'O que o cérebro faz quando aplica o viés de representatividade?', 'sesgo'),
  ('sesgo.authority-bias.fixation.2.option.0', 'pt-BR', 'Classifica algo novo pela semelhança com um estereótipo, ignorando a probabilidade estatística real', 'sesgo'),
  ('sesgo.authority-bias.fixation.2.option.1', 'pt-BR', 'Representa mentalmente os cenários futuros para tomar melhores decisões', 'sesgo'),
  ('sesgo.authority-bias.fixation.2.option.2', 'pt-BR', 'Usa a experiência passada de forma sistemática e precisa para avaliar situações novas', 'sesgo'),
  ('sesgo.regret-aversion.name', 'pt-BR', 'Aversão ao Arrependimento', 'sesgo'),
  ('sesgo.regret-aversion.definition', 'pt-BR', 'Evitamos tomar decisões por medo de que o resultado seja ruim e nos faça sentir responsáveis pela perda.', 'sesgo'),
  ('sesgo.regret-aversion.description', 'pt-BR', 'A Aversão ao Arrependimento é diferente da Aversão ao Risco clássica: não é medo de perder dinheiro, é medo de se sentir responsável por tê-lo perdido. Isso leva a dois comportamentos opostos: paralisia (não fazer nada para não errar ativamente) e comportamento de manada (se todos erram, a culpa não é só sua).', 'sesgo'),
  ('sesgo.regret-aversion.mechanism', 'pt-BR', 'Kahneman explica que o arrependimento é uma emoção contrafactual: o cérebro simula a realidade alternativa ("se ao menos eu tivesse…"). A dor é mais intensa quando a perda resulta de uma ação que tomamos do que de uma omissão. Isso cria uma assimetria que paralisa a tomada de decisão.', 'sesgo'),
  ('sesgo.regret-aversion.trapQuestion', 'pt-BR', 'O Fundo A perdeu 10% mantendo sua estratégia padrão. O Fundo B perdeu 10% após tentar uma nova estratégia. Qual gestor você demite? — A maioria demite o de B, mesmo que o resultado seja idêntico. Punimos mais o erro por ação do que por omissão.', 'sesgo'),
  ('sesgo.regret-aversion.example.0.label', 'pt-BR', 'Efeito disposição', 'sesgo'),
  ('sesgo.regret-aversion.example.0.text', 'pt-BR', 'Um investidor mantém uma ação perdedora por anos porque vendê-la "tornaria real" a perda e teria de admitir que errou. Vende as ganhadoras para garantir os ganhos antes que "se vão".', 'sesgo'),
  ('sesgo.regret-aversion.example.1.label', 'pt-BR', 'Manada', 'sesgo'),
  ('sesgo.regret-aversion.example.1.text', 'pt-BR', 'Um gestor investe no mesmo que todos os seus colegas. Se perder, "todos perdemos" — o arrependimento se dilui. Se tivesse tomado uma posição contrária e perdido, a culpa seria exclusivamente dele.', 'sesgo'),
  ('sesgo.regret-aversion.example.2.label', 'pt-BR', 'Inação', 'sesgo'),
  ('sesgo.regret-aversion.example.2.text', 'pt-BR', 'Uma pessoa com dinheiro em caixa por um ano que "aguarda o momento certo" para investir. O medo do arrependimento de entrar na hora errada supera o custo de oportunidade de ficar fora do mercado.', 'sesgo'),
  ('sesgo.regret-aversion.antidote.0', 'pt-BR', 'Distinga processo de resultado: foi uma boa decisão dado o que você sabia, mesmo que o resultado tenha sido ruim?', 'sesgo'),
  ('sesgo.regret-aversion.antidote.1', 'pt-BR', 'Reencadre o imobilismo: não decidir também é uma decisão — e também pode gerar arrependimento.', 'sesgo'),
  ('sesgo.regret-aversion.antidote.2', 'pt-BR', 'Regra do "10-10-10" (Suzy Welch): como você vai se sentir sobre essa decisão em 10 minutos, 10 meses e 10 anos?', 'sesgo'),
  ('sesgo.regret-aversion.antidote.3', 'pt-BR', 'Portfólio de "arrependimento mínimo": desenhe sua estratégia para que você consiga conviver com o pior cenário possível.', 'sesgo'),
  ('sesgo.regret-aversion.question.0.situation', 'pt-BR', 'O Fundo A perdeu -10% mantendo sua estratégia conservadora de sempre. O Fundo B perdeu -10% após mudar para uma nova estratégia. Quem você demite?', 'sesgo'),
  ('sesgo.regret-aversion.question.0.option.0.text', 'pt-BR', 'Ao gestor do Fundo B — tentou algo novo e falhou', 'sesgo'),
  ('sesgo.regret-aversion.question.0.option.0.reveal', 'pt-BR', 'Viés de omissão: punimos mais os erros por ação do que por inação, mesmo que o resultado seja idêntico', 'sesgo'),
  ('sesgo.regret-aversion.question.0.option.1.text', 'pt-BR', 'A nenhum / São equivalentes — o resultado foi o mesmo', 'sesgo'),
  ('sesgo.regret-aversion.question.0.option.1.reveal', 'pt-BR', 'Racional: o resultado foi idêntico. Se o Fundo B tivesse ganho com a nova estratégia, você teria parabenizado o gestor pela mesma decisão', 'sesgo'),
  ('sesgo.regret-aversion.question.1.situation', 'pt-BR', 'Você tem R$ 150.000 em caixa esperando "o momento certo" para investir. Já faz 14 meses que você espera. O que você faz?', 'sesgo'),
  ('sesgo.regret-aversion.question.1.option.0.text', 'pt-BR', 'Continuo esperando — se eu entrar e o mercado cair, vou me arrepender de não ter esperado', 'sesgo'),
  ('sesgo.regret-aversion.question.1.option.0.reveal', 'pt-BR', 'Aversão ao arrependimento por ação: mas quanto custou de oportunidade esse um ano e meio em caixa?', 'sesgo'),
  ('sesgo.regret-aversion.question.1.option.1.text', 'pt-BR', 'Entro de forma escalonada — o custo de oportunidade de esperar também gera arrependimento', 'sesgo'),
  ('sesgo.regret-aversion.question.1.option.1.reveal', 'pt-BR', 'Racional: a inação também gera arrependimento futuro. O dollar-cost averaging reduz a dor de "entrar no topo"', 'sesgo'),
  ('sesgo.regret-aversion.question.2.situation', 'pt-BR', 'Você precisa liquidar uma posição com urgência. Tem: Ação A (+20%) e Ação B (-25%). Ambas com igual potencial futuro. Qual você vende?', 'sesgo'),
  ('sesgo.regret-aversion.question.2.option.0.text', 'pt-BR', 'Vendo a A (+20%) — garanto o ganho e não "torno real" a perda em B', 'sesgo'),
  ('sesgo.regret-aversion.question.2.option.0.reveal', 'pt-BR', 'Efeito disposição / Aversão ao arrependimento: vender a ganhadora e manter a perdedora é o viés clássico de Shefrin & Statman', 'sesgo'),
  ('sesgo.regret-aversion.question.2.option.1.text', 'pt-BR', 'Avalio qual tem melhor perspectiva futura e vendo a que me convence menos', 'sesgo'),
  ('sesgo.regret-aversion.question.2.option.1.reveal', 'pt-BR', 'Racional: o preço de entrada é irrelevante para a decisão de hoje. Só importa o potencial futuro', 'sesgo'),
  ('sesgo.regret-aversion.fixation.0.question', 'pt-BR', 'Qual é a diferença entre um erro de comissão e um de omissão na aversão ao arrependimento?', 'sesgo'),
  ('sesgo.regret-aversion.fixation.0.option.0', 'pt-BR', 'O erro de comissão é agir e dar errado; o de omissão é não agir e perder uma oportunidade — o primeiro dói mais', 'sesgo'),
  ('sesgo.regret-aversion.fixation.0.option.1', 'pt-BR', 'O erro de comissão é não fazer nada; o de omissão é agir sem informação suficiente', 'sesgo'),
  ('sesgo.regret-aversion.fixation.0.option.2', 'pt-BR', 'Ambos geram o mesmo nível de arrependimento segundo as pesquisas de Kahneman', 'sesgo'),
  ('sesgo.regret-aversion.fixation.1.question', 'pt-BR', 'Um investidor não vende uma posição perdedora porque "se eu vender e subir, não vou me perdoar". Que viés explica a paralisia?', 'sesgo'),
  ('sesgo.regret-aversion.fixation.1.option.0', 'pt-BR', 'Aversão ao arrependimento: o medo do arrependimento futuro pesa mais do que a análise racional presente', 'sesgo'),
  ('sesgo.regret-aversion.fixation.1.option.1', 'pt-BR', 'Efeito dotação: supervaloriza a posição por já possuí-la', 'sesgo'),
  ('sesgo.regret-aversion.fixation.1.option.2', 'pt-BR', 'Viés de status quo: prefere não tomar decisões ativas', 'sesgo'),
  ('sesgo.regret-aversion.fixation.2.question', 'pt-BR', 'Como o comportamento de manada pode ser uma forma de gerenciar o arrependimento?', 'sesgo'),
  ('sesgo.regret-aversion.fixation.2.option.0', 'pt-BR', 'Se perdemos dinheiro seguindo a todos, o arrependimento é menor porque todos perderam — errar sozinho dói mais', 'sesgo'),
  ('sesgo.regret-aversion.fixation.2.option.1', 'pt-BR', 'Seguir a manada reduz o arrependimento porque a decisão coletiva é sempre mais precisa', 'sesgo'),
  ('sesgo.regret-aversion.fixation.2.option.2', 'pt-BR', 'O comportamento de manada elimina o arrependimento porque distribui a responsabilidade legalmente', 'sesgo'),
  ('sesgo.escalation-commitment.name', 'pt-BR', 'Escalada de Compromisso', 'sesgo'),
  ('sesgo.escalation-commitment.definition', 'pt-BR', 'Continuamos investindo em um projeto ou posição porque já investimos nele, não porque tenha potencial futuro.', 'sesgo'),
  ('sesgo.escalation-commitment.description', 'pt-BR', 'A Falácia do Custo Afundado é uma combinação de Erro Cognitivo (Contabilidade Mental, Enquadramento Restrito) e Viés Emocional (Aversão à Perda, Aversão ao Arrependimento). É o viés que mantém projetos fracassados vivos, carteiras cheias de posições perdedoras e pessoas em relacionamentos que já não funcionam.', 'sesgo'),
  ('sesgo.escalation-commitment.mechanism', 'pt-BR', 'Kahneman explica que nos recusamos a "fechar a conta mental" com saldo negativo. A aversão à perda faz com que investir mais pareça a única forma de "recuperar". A responsabilidade pessoal amplifica o efeito: quanto mais fomos os criadores da decisão original, mais difícil é abandoná-la.', 'sesgo'),
  ('sesgo.escalation-commitment.trapQuestion', 'pt-BR', 'Você é consultor externo. Um cliente leva anos financiando um projeto que já não tem demanda. O que você recomenda? — No frio, 90% diz "cancelar". Mas quando é o SEU projeto, com o SEU dinheiro, a resposta muda.', 'sesgo'),
  ('sesgo.escalation-commitment.example.0.label', 'pt-BR', 'Empresarial (Concorde)', 'sesgo'),
  ('sesgo.escalation-commitment.example.0.text', 'pt-BR', 'Os governos da França e do Reino Unido continuaram financiando o Concorde por anos após saberem que era economicamente inviável. Não conseguiam admitir o erro.', 'sesgo'),
  ('sesgo.escalation-commitment.example.1.label', 'pt-BR', 'Investimento', 'sesgo'),
  ('sesgo.escalation-commitment.example.1.text', 'pt-BR', 'Uma ação que você comprou a R$ 100 está valendo R$ 30. Você continua mantendo e comprando mais, não porque acredite na empresa, mas porque "não consegue vender a esse preço".', 'sesgo'),
  ('sesgo.escalation-commitment.example.2.label', 'pt-BR', 'Pessoal', 'sesgo'),
  ('sesgo.escalation-commitment.example.2.text', 'pt-BR', 'Você está há 2 anos em uma pós-graduação que não gosta e não é relevante para sua carreira. Continua porque "já investi muito tempo e dinheiro".', 'sesgo'),
  ('sesgo.escalation-commitment.antidote.0', 'pt-BR', 'Teste do Novo CEO: "Se eu chegasse hoje sem histórico com este projeto, continuaria ou cancelaria?"', 'sesgo'),
  ('sesgo.escalation-commitment.antidote.1', 'pt-BR', 'Reformular a pergunta: "Quanto eu investiria HOJE nisso se estivesse começando do zero?"', 'sesgo'),
  ('sesgo.escalation-commitment.antidote.2', 'pt-BR', 'Stop-loss predefinidos: antes de investir, defina quando e em quais condições você sairia.', 'sesgo'),
  ('sesgo.escalation-commitment.antidote.3', 'pt-BR', 'Reinterpretar o fracasso: a perda já aconteceu — a pergunta é apenas o que fazer daqui para frente.', 'sesgo'),
  ('sesgo.escalation-commitment.question.0.situation', 'pt-BR', 'Você comprou ações de uma empresa a R$ 100. Hoje valem R$ 40. Há 8 meses aguardando a recuperação. Que perguntas você se faz?', 'sesgo'),
  ('sesgo.escalation-commitment.question.0.option.0.text', 'pt-BR', 'Como posso recuperar os R$ 60 que perdi?', 'sesgo'),
  ('sesgo.escalation-commitment.question.0.option.0.reveal', 'pt-BR', 'Escalada de compromisso: os R$ 60 já se perderam. A pergunta correta é sobre o futuro, não o passado', 'sesgo'),
  ('sesgo.escalation-commitment.question.0.option.1.text', 'pt-BR', 'Se eu tivesse R$ 40 em dinheiro hoje, compraria essa ação a R$ 40?', 'sesgo'),
  ('sesgo.escalation-commitment.question.0.option.1.reveal', 'pt-BR', 'Racional: este é o Teste do Novo CEO — a decisão deve se basear no futuro, não em recuperar o passado', 'sesgo'),
  ('sesgo.escalation-commitment.question.1.situation', 'pt-BR', 'Sua startup está há 18 meses sem tração. Você já gastou R$ 250 mil. Os clientes não adotam o produto. Você tem R$ 60 mil no caixa. O que você faz?', 'sesgo'),
  ('sesgo.escalation-commitment.question.1.option.0.text', 'pt-BR', 'Injeto os R$ 60 mil restantes — não posso desistir depois de tanto sacrifício', 'sesgo'),
  ('sesgo.escalation-commitment.question.1.option.0.reveal', 'pt-BR', 'Escalada de compromisso: os R$ 250 mil já não podem ser recuperados. A pergunta é se os R$ 60 mil têm melhor retorno neste projeto ou em outro', 'sesgo'),
  ('sesgo.escalation-commitment.question.1.option.1.text', 'pt-BR', 'Avalio se há evidências novas que justifiquem continuar, ou se é hora de um pivot ou encerramento', 'sesgo'),
  ('sesgo.escalation-commitment.question.1.option.1.reveal', 'pt-BR', 'Racional: a decisão é tomada com os dados atuais, não com o peso emocional do passado', 'sesgo'),
  ('sesgo.escalation-commitment.question.2.situation', 'pt-BR', 'Você está há 3 anos em um projeto profissional que te deixa infeliz. Sua lógica para ficar é "já investi muito aqui". É um bom argumento?', 'sesgo'),
  ('sesgo.escalation-commitment.question.2.option.0.text', 'pt-BR', 'Sim — é válido considerar tudo o que construí antes de pedir demissão', 'sesgo'),
  ('sesgo.escalation-commitment.question.2.option.0.reveal', 'pt-BR', 'Escalada de compromisso: o que você já investiu não muda o que você vai ganhar ou perder daqui para frente. A decisão parte de hoje', 'sesgo'),
  ('sesgo.escalation-commitment.question.2.option.1.text', 'pt-BR', 'Não — o que já investi não vou recuperar. A pergunta é o que quero construir a partir de hoje', 'sesgo'),
  ('sesgo.escalation-commitment.question.2.option.1.reveal', 'pt-BR', 'Racional: o tempo passado não pode ser recuperado. Só o tempo futuro está em jogo', 'sesgo'),
  ('sesgo.escalation-commitment.fixation.0.question', 'pt-BR', 'O que distingue a escalada de compromisso de simplesmente ser perseverante?', 'sesgo'),
  ('sesgo.escalation-commitment.fixation.0.option.0', 'pt-BR', 'A escalada ignora evidências negativas novas e continua pelo que já foi investido; a perseverança responde a fundamentos reais', 'sesgo'),
  ('sesgo.escalation-commitment.fixation.0.option.1', 'pt-BR', 'A escalada só ocorre em grandes investimentos; a perseverança se aplica a decisões cotidianas', 'sesgo'),
  ('sesgo.escalation-commitment.fixation.0.option.2', 'pt-BR', 'A perseverança é sempre racional; a escalada é sempre irracional sem exceção', 'sesgo'),
  ('sesgo.escalation-commitment.fixation.1.question', 'pt-BR', 'Um CEO leva 3 anos defendendo uma divisão que dá prejuízo. Os dados pioram a cada trimestre. Quais vieses combinados explicam seu comportamento?', 'sesgo'),
  ('sesgo.escalation-commitment.fixation.1.option.0', 'pt-BR', 'Escalada de compromisso + aversão à perda + ilusão de controle: não consegue admitir o fracasso e acredita que pode revertê-lo', 'sesgo'),
  ('sesgo.escalation-commitment.fixation.1.option.1', 'pt-BR', 'Excesso de confiança + efeito manada: confia que o mercado eventualmente validará sua estratégia', 'sesgo'),
  ('sesgo.escalation-commitment.fixation.1.option.2', 'pt-BR', 'Viés de confirmação + representatividade: interpreta os dados negativos como casos excepcionais', 'sesgo'),
  ('sesgo.escalation-commitment.fixation.2.question', 'pt-BR', 'O que é a "tática do novo CEO" como antídoto à escalada?', 'sesgo'),
  ('sesgo.escalation-commitment.fixation.2.option.0', 'pt-BR', 'Perguntar-se: "Se eu chegasse hoje sem histórico neste projeto, tomaria essa mesma decisão?" — julgar sem bagagem emocional', 'sesgo'),
  ('sesgo.escalation-commitment.fixation.2.option.1', 'pt-BR', 'Contratar um consultor externo que não tenha vínculos com o projeto para avaliá-lo objetivamente', 'sesgo'),
  ('sesgo.escalation-commitment.fixation.2.option.2', 'pt-BR', 'Estabelecer desde o início critérios claros de sucesso e fracasso que não possam ser modificados depois', 'sesgo'),
  ('sesgo.anclaje.name', 'pt-BR', 'Ancoragem e Ajuste', 'sesgo'),
  ('sesgo.anclaje.definition', 'pt-BR', 'Dependemos excessivamente de um valor inicial (a "âncora") para fazer estimativas, ajustando de forma insuficiente a partir desse ponto.', 'sesgo'),
  ('sesgo.anclaje.description', 'pt-BR', 'O viés de Ancoragem e Ajuste, descrito por Kahneman e Tversky, mostra que qualquer número que vejamos primeiro age como ponto de referência que contamina todas as estimativas posteriores. Dan Ariely chama isso de "Coerência Arbitrária": o primeiro preço que vemos se torna o padrão mental, mesmo que tenha sido completamente aleatório.', 'sesgo'),
  ('sesgo.anclaje.mechanism', 'pt-BR', 'O Sistema 1 é insuficientemente crítico com a âncora inicial. O ajuste a partir da âncora é sempre insuficiente porque paramos no primeiro valor "plausível". Não importa se a âncora é relevante ou absurda — seu efeito persiste.', 'sesgo'),
  ('sesgo.anclaje.trapQuestion', 'pt-BR', 'Quantas pessoas há na Turquia? Agora: antes, me diga — há mais ou menos de 10 milhões? — Depois de pensar em 10M, sua resposta será diferente do que se eu tivesse dito 100M primeiro. O número arbitrário te ancorou.', 'sesgo'),
  ('sesgo.anclaje.example.0.label', 'pt-BR', 'Negociação', 'sesgo'),
  ('sesgo.anclaje.example.0.text', 'pt-BR', 'Em uma negociação salarial, quem coloca o primeiro número na mesa ancora toda a discussão. Quem responde sempre ajusta a partir desse ponto, não a partir do seu valor real.', 'sesgo'),
  ('sesgo.anclaje.example.1.label', 'pt-BR', 'Investimento', 'sesgo'),
  ('sesgo.anclaje.example.1.text', 'pt-BR', 'Uma ação que você comprou a R$ 200 e agora vale R$ 80. Sua âncora é R$ 200 e você percebe R$ 80 como "barata", embora R$ 80 ainda possa ser cara com base nos fundamentals atuais.', 'sesgo'),
  ('sesgo.anclaje.example.2.label', 'pt-BR', 'Preços', 'sesgo'),
  ('sesgo.anclaje.example.2.text', 'pt-BR', 'Em um restaurante, o vinho mais caro do cardápio existe para fazer o segundo mais caro parecer razoável — o preço alto ancora a percepção de valor.', 'sesgo'),
  ('sesgo.anclaje.antidote.0', 'pt-BR', 'Defina sua estimativa ANTES de ver qualquer preço ou número de referência.', 'sesgo')
INSERT INTO public.translations (key, lang, text, domain) VALUES
  ('sesgo.anclaje.antidote.1', 'pt-BR', 'Pergunte-se: "Minha estimativa seria a mesma se eu nunca tivesse visto esse número?"', 'sesgo'),
  ('sesgo.anclaje.antidote.2', 'pt-BR', 'Use múltiplas metodologias de valuation independentes antes de comparar.', 'sesgo'),
  ('sesgo.anclaje.antidote.3', 'pt-BR', 'Em negociações: se o outro ancorar primeiro, aponte explicitamente que a âncora é arbitrária antes de fazer uma contraproposta.', 'sesgo'),
  ('sesgo.anclaje.question.0.situation', 'pt-BR', 'Uma ação que você comprou a R$ 150 agora está cotada a R$ 60. O analista diz que o preço justo é R$ 55. Como você percebe R$ 60?', 'sesgo'),
  ('sesgo.anclaje.question.0.option.0.text', 'pt-BR', 'Está barata — está muito abaixo dos R$ 150 que paguei', 'sesgo'),
  ('sesgo.anclaje.question.0.option.0.reveal', 'pt-BR', 'Ancoragem: seu preço de compra (R$ 150) contamina sua percepção do valor atual. R$ 60 pode ser caro se o valor justo é R$ 55', 'sesgo'),
  ('sesgo.anclaje.question.0.option.1.text', 'pt-BR', 'Avalio se R$ 60 está barata ou cara com base na análise atual, não no que paguei', 'sesgo'),
  ('sesgo.anclaje.question.0.option.1.reveal', 'pt-BR', 'Racional: o preço de compra é historicamente irrelevante para a decisão de hoje', 'sesgo'),
  ('sesgo.anclaje.question.1.situation', 'pt-BR', 'Você vai negociar seu salário. Qual é a sua estratégia?', 'sesgo'),
  ('sesgo.anclaje.question.1.option.0.text', 'pt-BR', 'Espero o empregador propor primeiro — não quero passar mal pedindo muito', 'sesgo'),
  ('sesgo.anclaje.question.1.option.0.reveal', 'pt-BR', 'Erro: quem ancora primeiro leva vantagem. Quem menciona um número primeiro estabelece o ponto de referência para toda a negociação', 'sesgo'),
  ('sesgo.anclaje.question.1.option.1.text', 'pt-BR', 'Proponho primeiro um número alto mas razoável — quero ancorar eu a conversa', 'sesgo'),
  ('sesgo.anclaje.question.1.option.1.reveal', 'pt-BR', 'Racional: ancorar primeiro com um número ambicioso mas crível direciona o acordo final a seu favor', 'sesgo'),
  ('sesgo.anclaje.question.2.situation', 'pt-BR', 'Você vê um relógio de R$ 5.000 na vitrine de uma loja de luxo. Entra para perguntar sobre um relógio que estava procurando. Oferecem um por R$ 1.200. Como você o percebe?', 'sesgo'),
  ('sesgo.anclaje.question.2.option.0.text', 'pt-BR', 'Parece razoável — é muito menos que o de R$ 5.000 da vitrine', 'sesgo'),
  ('sesgo.anclaje.question.2.option.0.reveal', 'pt-BR', 'Ancoragem por design: lojas de luxo colocam artigos caros na vitrine exatamente para ancorar sua percepção de valor', 'sesgo'),
  ('sesgo.anclaje.question.2.option.1.text', 'pt-BR', 'Avalio R$ 1.200 como se não tivesse visto o relógio de R$ 5.000 — esse preço é justo para o que eu quero?', 'sesgo'),
  ('sesgo.anclaje.question.2.option.1.reveal', 'pt-BR', 'Racional: a âncora foi colocada intencionalmente para contaminar sua avaliação', 'sesgo'),
  ('sesgo.anclaje.fixation.0.question', 'pt-BR', 'O que é a "âncora" no viés de ancoragem?', 'sesgo'),
  ('sesgo.anclaje.fixation.0.option.0', 'pt-BR', 'O primeiro dado que recebemos e que influencia desproporcionalmente nossa estimativa', 'sesgo'),
  ('sesgo.anclaje.fixation.0.option.1', 'pt-BR', 'O preço final que pagamos por um produto', 'sesgo'),
  ('sesgo.anclaje.fixation.0.option.2', 'pt-BR', 'A decisão mais racional em uma negociação', 'sesgo'),
  ('sesgo.anclaje.fixation.1.question', 'pt-BR', 'Um vendedor anuncia preço original R$ 10.000 com 50% de desconto. Qual é o efeito da ancoragem?', 'sesgo'),
  ('sesgo.anclaje.fixation.1.option.0', 'pt-BR', 'O desconto nos faz acreditar que R$ 5.000 é uma pechincha, embora não saibamos se esse era o preço justo', 'sesgo'),
  ('sesgo.anclaje.fixation.1.option.1', 'pt-BR', 'O preço de R$ 5.000 é objetivamente barato porque baixou', 'sesgo'),
  ('sesgo.anclaje.fixation.1.option.2', 'pt-BR', 'Só há ancoragem se o comprador conhecia o preço original antes', 'sesgo'),
  ('sesgo.anclaje.fixation.2.question', 'pt-BR', 'Segundo Dan Ariely, o que é a "coerência arbitrária"?', 'sesgo'),
  ('sesgo.anclaje.fixation.2.option.0', 'pt-BR', 'Os preços iniciais aleatórios se tornam o padrão mental com o qual comparamos tudo o mais', 'sesgo'),
  ('sesgo.anclaje.fixation.2.option.1', 'pt-BR', 'As pessoas sempre negociam de forma coerente mesmo que os preços sejam arbitrários', 'sesgo'),
  ('sesgo.anclaje.fixation.2.option.2', 'pt-BR', 'O cérebro ignora os preços iniciais e decide apenas com informação nova', 'sesgo'),
  ('profile.PP.name', 'pt-BR', 'Passive Preserver', 'profile'),
  ('profile.PP.nameEs', 'pt-BR', 'Preservador Passivo', 'profile'),
  ('profile.PP.tagline', 'pt-BR', 'Emocional · Passivo — Sua prioridade é proteger o que você tem', 'profile'),
  ('profile.PP.description', 'pt-BR', 'Você tende a priorizar a segurança e a preservação do seu patrimônio acima do crescimento. Suas decisões financeiras são fortemente influenciadas pelo medo de perder. Você é cuidadoso e constante, mas corre o risco de a inflação corroer seu capital ao evitar o risco necessário.', 'profile'),
  ('profile.PP.bias.0.name', 'pt-BR', 'Aversão à perda', 'profile'),
  ('profile.PP.bias.0.desc', 'pt-BR', 'Você sente as perdas com mais intensidade do que os ganhos equivalentes. Perder R$ 300 dói mais do que ganhar R$ 300 alegra.', 'profile'),
  ('profile.PP.bias.1.name', 'pt-BR', 'Viés de Status Quo', 'profile'),
  ('profile.PP.bias.1.desc', 'pt-BR', 'Você prefere manter as coisas como estão, mesmo quando mudar poderia te beneficiar. "Antes o mal conhecido do que o bem por conhecer."', 'profile'),
  ('profile.PP.bias.2.name', 'pt-BR', 'Efeito dotação', 'profile'),
  ('profile.PP.bias.2.desc', 'pt-BR', 'Você supervaloriza o que já possui simplesmente porque é seu, o que te torna resistente a vender ou trocar.', 'profile'),
  ('profile.PP.recommendation.0', 'pt-BR', 'Entenda que a inflação é um risco silencioso: não investir também é arriscar.', 'profile'),
  ('profile.PP.recommendation.1', 'pt-BR', 'Comece com instrumentos de baixo risco mas com rendimento real (Tesouro Direto, CDBs).', 'profile'),
  ('profile.PP.recommendation.2', 'pt-BR', 'Estabeleça regras claras antes de investir para que as emoções não dominem.', 'profile'),
  ('profile.PP.recommendation.3', 'pt-BR', 'Diversifique gradualmente — você não precisa fazer mudanças drásticas, mas precisa se movimentar.', 'profile'),
  ('profile.FK.name', 'pt-BR', 'Friendly Follower', 'profile'),
  ('profile.FK.nameEs', 'pt-BR', 'Seguidor Amistoso', 'profile'),
  ('profile.FK.tagline', 'pt-BR', 'Cognitivo · Passivo — Você busca orientação em pessoas de confiança', 'profile'),
  ('profile.FK.description', 'pt-BR', 'Você tende a buscar a opinião de outras pessoas antes de tomar decisões financeiras. Não é que você não pense — você valoriza a validação social e o conselho de figuras de autoridade. Seu risco está em confiar em vozes que soam seguras, mas que não necessariamente têm razão.', 'profile'),
  ('profile.FK.bias.0.name', 'pt-BR', 'Efeito manada (Herding)', 'profile'),
  ('profile.FK.bias.0.desc', 'pt-BR', 'Você tende a seguir o que a maioria faz. Se todos compram, você compra. A multidão nem sempre tem razão.', 'profile'),
  ('profile.FK.bias.1.name', 'pt-BR', 'Viés de Autoridade', 'profile'),
  ('profile.FK.bias.1.desc', 'pt-BR', 'Você dá peso excessivo à opinião de figuras que percebe como especialistas, sem questionar se realmente o são.', 'profile'),
  ('profile.FK.bias.2.name', 'pt-BR', 'Viés de disponibilidade', 'profile'),
  ('profile.FK.bias.2.desc', 'pt-BR', 'Você dá mais importância à informação mais recente e visível. Se o mercado subiu essa semana, você acredita que vai continuar subindo.', 'profile'),
  ('profile.FK.recommendation.0', 'pt-BR', 'Desenvolva seu próprio critério: antes de perguntar para alguém, escreva o que você faria e por quê.', 'profile'),
  ('profile.FK.recommendation.1', 'pt-BR', 'Questione as fontes: essa pessoa realmente sabe, ou apenas parece segura?', 'profile'),
  ('profile.FK.recommendation.2', 'pt-BR', 'Diversifique suas fontes de informação — não dependa de uma única pessoa.', 'profile'),
  ('profile.FK.recommendation.3', 'pt-BR', 'Pratique tomar decisões pequenas por conta própria para construir confiança.', 'profile'),
  ('profile.II.name', 'pt-BR', 'Independent Individualist', 'profile'),
  ('profile.II.nameEs', 'pt-BR', 'Individualista Independente', 'profile'),
  ('profile.II.tagline', 'pt-BR', 'Cognitivo · Ativo — Você analisa, pesquisa e decide por conta própria', 'profile'),
  ('profile.II.description', 'pt-BR', 'Você é analítico e autossuficiente. Pesquisa antes de decidir e confia no próprio julgamento. Seu risco está em acreditar que sempre tem razão e que sua análise é melhor do que realmente é.', 'profile'),
  ('profile.II.bias.0.name', 'pt-BR', 'Excesso de Confiança', 'profile'),
  ('profile.II.bias.0.desc', 'pt-BR', 'Você superestima sua capacidade de prever resultados. Sua análise pode ser sólida, mas não é infalível.', 'profile'),
  ('profile.II.bias.1.name', 'pt-BR', 'Viés de Confirmação', 'profile'),
  ('profile.II.bias.1.desc', 'pt-BR', 'Você busca informações que confirmam o que já acredita e ignora as que contradizem. Sua "pesquisa" pode ser seletiva.', 'profile'),
  ('profile.II.bias.2.name', 'pt-BR', 'Ilusão de controle', 'profile'),
  ('profile.II.bias.2.desc', 'pt-BR', 'Você acredita que pode controlar ou influenciar resultados que, na realidade, são incertos ou aleatórios.', 'profile'),
  ('profile.II.recommendation.0', 'pt-BR', 'Busque ativamente opiniões contrárias às suas — se você só lê o que confirma sua tese, não está pesquisando de verdade.', 'profile'),
  ('profile.II.recommendation.1', 'pt-BR', 'Aceite que o mercado pode ser irracional por mais tempo do que você consegue se manter solvente.', 'profile'),
  ('profile.II.recommendation.2', 'pt-BR', 'Mantenha um registro das suas previsões para medir sua precisão real, não a percebida.', 'profile'),
  ('profile.II.recommendation.3', 'pt-BR', 'Considere que pedir conselho não é fraqueza — até os melhores analistas têm pontos cegos.', 'profile'),
  ('profile.AA.name', 'pt-BR', 'Active Accumulator', 'profile'),
  ('profile.AA.nameEs', 'pt-BR', 'Acumulador Ativo', 'profile'),
  ('profile.AA.tagline', 'pt-BR', 'Emocional · Ativo — Você age rápido e busca crescimento', 'profile'),
  ('profile.AA.description', 'pt-BR', 'Você é decidido, arrojado e orientado à ação. Gosta de assumir o controle e não tem medo de arriscar. Seu risco é confundir atividade com progresso — mais operações nem sempre significam melhores resultados.', 'profile'),
  ('profile.AA.bias.0.name', 'pt-BR', 'Excesso de Confiança', 'profile'),
  ('profile.AA.bias.0.desc', 'pt-BR', 'Sua segurança ao agir pode fazer você subestimar os riscos reais.', 'profile'),
  ('profile.AA.bias.1.name', 'pt-BR', 'Ilusão de controle', 'profile'),
  ('profile.AA.bias.1.desc', 'pt-BR', 'Você acredita que, ao estar ativo e tomar decisões, controla o resultado. O acaso desempenha um papel maior do que você percebe.', 'profile'),
  ('profile.AA.bias.2.name', 'pt-BR', 'Viés de ação', 'profile'),
  ('profile.AA.bias.2.desc', 'pt-BR', 'Você prefere fazer algo — qualquer coisa — a não fazer nada. Às vezes a melhor decisão é esperar.', 'profile'),
  ('profile.AA.recommendation.0', 'pt-BR', 'Implemente regras de stop-loss e realização de ganhos ANTES de investir, não no momento.', 'profile'),
  ('profile.AA.recommendation.1', 'pt-BR', 'Não confunda atividade com produtividade — às vezes o melhor investimento é não fazer nada.', 'profile'),
  ('profile.AA.recommendation.2', 'pt-BR', 'Antes de agir por impulso, espere 24 horas. Se amanhã ainda parecer uma boa ideia, vá em frente.', 'profile'),
  ('profile.AA.recommendation.3', 'pt-BR', 'Calcule quanto suas decisões impulsivas já custaram — o número pode te surpreender.', 'profile'),
  ('report.mecanismo.dolor.name', 'pt-BR', 'Aversão à Dor', 'report'),
  ('report.mecanismo.dolor.phrase', 'pt-BR', 'O cérebro evita registrar perdas', 'report'),
  ('report.mecanismo.dolor.desc', 'pt-BR', 'O cérebro sente a dor de perder aproximadamente o dobro do prazer de ganhar (Kahneman & Tversky). Para evitar essa dor, distorce a realidade — adia decisões, inventa justificativas, apega-se ao passado.', 'report'),
  ('report.mecanismo.dolor.relation', 'pt-BR', 'Os vieses deste mecanismo fazem você manter investimentos perdedores "para não realizar a perda", supervalorizar o que já possui e continuar colocando dinheiro em decisões fracassadas pelo custo afundado.', 'report'),
  ('report.mecanismo.ego.name', 'pt-BR', 'Proteção do Ego', 'report'),
  ('report.mecanismo.ego.phrase', 'pt-BR', 'O cérebro distorce fatos para preservar a autoimagem', 'report'),
  ('report.mecanismo.ego.desc', 'pt-BR', 'Temos uma necessidade profunda de manter uma autoimagem positiva e coerente. Quando a realidade ameaça essa imagem, o cérebro prefere distorcer os fatos a revisar a crença que tem sobre si mesmo.', 'report'),
  ('report.mecanismo.ego.relation', 'pt-BR', 'Os vieses deste mecanismo fazem você enxergar apenas as informações que confirmam sua tese, atribuir seus sucessos à sua habilidade e os fracassos ao mercado, e superestimar sistematicamente sua precisão ao fazer previsões.', 'report'),
  ('report.mecanismo.econ.name', 'pt-BR', 'Economia Cognitiva', 'report'),
  ('report.mecanismo.econ.phrase', 'pt-BR', 'O cérebro substitui perguntas difíceis por atalhos', 'report'),
  ('report.mecanismo.econ.desc', 'pt-BR', 'O cérebro é preguiçoso por design — pensar consome energia. Para economizá-la, substitui perguntas difíceis ("qual é o valor intrínseco?") por atalhos fáceis ("como isso parece?"). O problema é que ele não avisa quando está fazendo isso.', 'report'),
  ('report.mecanismo.econ.relation', 'pt-BR', 'Os vieses deste mecanismo fazem você se ancorar no primeiro número que viu, tratar o dinheiro de forma diferente conforme sua origem e julgar probabilidades pela facilidade com que se lembra de exemplos.', 'report'),
  ('report.mecanismo.grupo.name', 'pt-BR', 'Necessidade de Pertencimento', 'report'),
  ('report.mecanismo.grupo.phrase', 'pt-BR', 'O cérebro terceiriza decisões para o grupo', 'report')
INSERT INTO public.translations (key, lang, text, domain) VALUES
  ('report.mecanismo.grupo.desc', 'pt-BR', 'O isolamento foi historicamente perigoso; por isso desenvolvemos um instinto poderoso de nos alinhar ao consenso, especialmente diante da incerteza. O cérebro trata o grupo como referência de verdade.', 'report'),
  ('report.mecanismo.grupo.relation', 'pt-BR', 'Os vieses deste mecanismo fazem você entrar em investimentos porque "todo mundo está entrando", obedecer a figuras de autoridade sem questionar e generalizar uma boa impressão a toda uma empresa ou pessoa.', 'report'),
  ('report.mecanismo.tiempo.name', 'pt-BR', 'Presente vs. Futuro', 'report'),
  ('report.mecanismo.tiempo.phrase', 'pt-BR', 'O cérebro supervaloriza o agora', 'report'),
  ('report.mecanismo.tiempo.desc', 'pt-BR', 'O cérebro tem dificuldade genuína de imaginar o eu futuro como uma pessoa real. Essa assimetria nos empurra a sacrificar sistematicamente o futuro pelo presente — não por falta de informação, mas por uma limitação cognitiva.', 'report'),
  ('report.mecanismo.tiempo.relation', 'pt-BR', 'Os vieses deste mecanismo fazem você manter o status quo por inércia, falhar na poupança de longo prazo por gastar hoje e postergar decisões importantes quando exigem esforço no presente.', 'report'),
  ('report.antidoto.precom.name', 'pt-BR', 'Pré-compromisso', 'report'),
  ('report.antidoto.precom.what', 'pt-BR', 'Tomar a decisão em estado frio, por escrito e com antecedência — antes que a situação emocional apareça.', 'report'),
  ('report.antidoto.precom.how', 'pt-BR', 'Defina hoje regras claras: "Se o mercado cair X%, rebalanceio. Se sobrar dinheiro no fim do mês, vai automaticamente para o meu fundo indexado." Automatize onde puder (transferências programadas) para que o seu eu futuro não precise decidir no momento.', 'report'),
  ('report.antidoto.diario.name', 'pt-BR', 'Diário de Decisões', 'report'),
  ('report.antidoto.diario.what', 'pt-BR', 'Registro escrito de cada decisão de investimento: tese, razões, resultado esperado, data — para poder revisar depois se houve habilidade ou sorte.', 'report'),
  ('report.antidoto.diario.how', 'pt-BR', 'Antes de cada investimento, escreva em 5 linhas: "Compro X porque Y. Espero o resultado Z para a data W. Vendo se acontecer A." Revise mensalmente. Com o tempo, você verá o padrão real dos seus acertos vs. suas justificativas posteriores.', 'report'),
  ('report.antidoto.s2.name', 'pt-BR', 'Ativar Sistema 2', 'report'),
  ('report.antidoto.s2.what', 'pt-BR', 'Interromper deliberadamente o modo automático (Sistema 1, rápido e emocional) para passar ao modo analítico (Sistema 2, lento e deliberado) antes de decidir.', 'report'),
  ('report.antidoto.s2.how', 'pt-BR', 'Imponha uma pausa: 24 horas entre o impulso e a ação. Durante essa pausa, faça 3 perguntas por escrito: "Que informação me falta? O que estou assumindo sem verificar? Como saberei se errei?" Se as respostas não forem claras, não decida ainda.', 'report'),
  ('report.antidoto.votcie.name', 'pt-BR', 'Votação Cega', 'report'),
  ('report.antidoto.votcie.what', 'pt-BR', 'Expressar sua opinião por escrito antes de ouvir a do grupo, para evitar que o consenso contamine seu julgamento.', 'report'),
  ('report.antidoto.votcie.how', 'pt-BR', 'Em reuniões ou comitês: antes de abrir a discussão, cada participante escreve sua posição em um papel. As posições são reveladas simultaneamente. Assim se quebra o efeito cascata em que todos se alinham com quem falou primeiro.', 'report'),
  ('report.antidoto.testnd.name', 'pt-BR', 'Teste do Dinheiro Novo', 'report'),
  ('report.antidoto.testnd.what', 'pt-BR', 'Tratar cada real como se acabasse de chegar às suas mãos — ignorando sua origem e seu histórico com ele.', 'report'),
  ('report.antidoto.testnd.how', 'pt-BR', 'Diante de um investimento perdedor, pergunte-se: "Se me dessem esse dinheiro hoje em mãos, compraria esta posição?" Se a resposta for não, venda. O preço que você pagou é irrelevante — só importam o presente e o futuro.', 'report'),
  ('report.antidoto.premortem.name', 'pt-BR', 'Pré-mortem', 'report'),
  ('report.antidoto.premortem.what', 'pt-BR', 'Imaginar que sua decisão já fracassou e voltar no tempo para identificar por quê — antes de tomá-la.', 'report'),
  ('report.antidoto.premortem.how', 'pt-BR', 'Antes de agir, escreva: "Estamos 12 meses no futuro. Este investimento foi um desastre. O que deu errado?" Liste 5 razões plausíveis. Se alguma tiver probabilidade real, ajuste o plano ou não invista. Funciona porque desativa o excesso de otimismo.', 'report'),
  ('report.antidoto.steelman.name', 'pt-BR', 'Steel-manning', 'report'),
  ('report.antidoto.steelman.what', 'pt-BR', 'Construir o melhor argumento possível CONTRA a sua própria tese — o oposto do "straw-man" que simplifica o oponente.', 'report'),
